const fs = require('fs');
const path = require('path');

const reportPath = path.join(process.cwd(), 'eslint-report.json');
const report = JSON.parse(fs.readFileSync(reportPath, 'utf8'));

let fixedCount = 0;
let failedCount = 0;

for (const file of report) {
  if (file.messages.length === 0) continue;

  const unusedMsgs = file.messages.filter(m => m.ruleId === '@typescript-eslint/no-unused-vars' || m.ruleId === 'no-unused-vars');
  if (unusedMsgs.length === 0) continue;

  let content = fs.readFileSync(file.filePath, 'utf8');
  let lines = content.split('\n');
  let modified = false;

  // Process in reverse order so line numbers don't shift!
  // Wait, line numbers only shift if we add/remove lines.
  // We will try not to add/remove lines, or just do it line by line carefully.
  // Actually, replacing within the line is better.

  // Group by line number
  const byLine = {};
  for (const msg of unusedMsgs) {
    if (!byLine[msg.line]) byLine[msg.line] = [];
    byLine[msg.line].push(msg);
  }

  const lineNumbers = Object.keys(byLine).map(Number).sort((a, b) => b - a); // reverse order

  for (const lineNum of lineNumbers) {
    let lineStr = lines[lineNum - 1];
    const msgs = byLine[lineNum];

    // Extract var names
    const varNames = msgs.map(m => {
      const match = m.message.match(/'([^']+)'/);
      return match ? match[1] : null;
    }).filter(Boolean);

    let newLine = lineStr;
    let isImport = newLine.trim().startsWith('import');

    for (const v of varNames) {
      if (isImport) {
        // Handle import
        // Try to remove `, v` or `v,` or `v` from `{ ... }`
        const regex1 = new RegExp(`\\s*,\\s*${v}\\b`);
        const regex2 = new RegExp(`\\b${v}\\s*,\\s*`);
        const regex3 = new RegExp(`\\{\\s*${v}\\s*\\}`);
        const regex4 = new RegExp(`\\b${v}\\b`);

        if (regex1.test(newLine)) {
          newLine = newLine.replace(regex1, '');
        } else if (regex2.test(newLine)) {
          newLine = newLine.replace(regex2, '');
        } else if (regex3.test(newLine)) {
          // It was the only named import, e.g. import { v } from 'x'
          // We can remove the whole import, but maybe there's a default import?
          // e.g. import defaultImport, { v } from 'x'
          newLine = newLine.replace(new RegExp(`,\\s*\\{\\s*${v}\\s*\\}`), ''); // remove `, { v }`
          newLine = newLine.replace(new RegExp(`\\{\\s*${v}\\s*\\}\\s*,`), ''); // remove `{ v }, `
          newLine = newLine.replace(new RegExp(`\\{\\s*${v}\\s*\\}`), ''); // remove `{ v }` entirely
        } else {
          // default import? 
          newLine = newLine.replace(new RegExp(`\\b${v}\\b\\s*,?\\s*`), '');
        }

        // Cleanup empty named imports `import {} from ...`
        newLine = newLine.replace(/\{\s*\}/, '');
        // If line is just `import from '...'` or `import '...'`, well, if it's side effect it's fine.
        if (newLine.trim().match(/^import\s+from\s+['"]/)) {
          newLine = ''; // empty line
        }
      } else {
        // Not an import, just prefix with _
        const regex = new RegExp(`\\b${v}\\b`, 'g');
        // Only replace the definition? The linter points to the line of definition.
        // It's safe-ish to replace the first occurrence on this line, or all on this line if it's unused anyway.
        // Let's replace only occurrences that are not already prefixed (which shouldn't happen)
        // Actually, just replace `\bV\b` with `_V`.

        // Edge case: object destructuring with alias: `const { x: V } = obj` -> `const { x: _V } = obj`
        // Edge case: shorthand destructuring: `const { V } = obj` -> `const { V: _V } = obj`

        // Let's try to detect shorthand destructuring first:
        const shorthandRegex = new RegExp(`\\{\\s*([^}]*\\s*,\\s*)?(${v})(\\s*,\\s*[^}]*)?\\s*\\}`);
        if (shorthandRegex.test(newLine)) {
          // Replace `v` with `v: _${v}` ONLY inside the braces.
          // This is tricky with simple regex. Let's just do a simple replace of the word.
          // If it is inside { }, replace `v` with `v: _${v}`.
          // Simple heuristic: if the line contains `{` and `}`, and `v` is inside.

          let parts = newLine.split(v);
          if (parts.length > 1) {
            // Find the index of the first occurrence
            let before = newLine.substring(0, newLine.indexOf(v));
            let after = newLine.substring(newLine.indexOf(v) + v.length);

            // Check if we are inside destructuring by looking at `{` and `:`
            if (before.includes('{') && !before.substring(before.lastIndexOf('{')).includes(':')) {
              if (after.trim().startsWith(',')) {
                 newLine = before + `${v}: _${v}` + after;
              } else if (after.trim().startsWith('}')) {
                 newLine = before + `${v}: _${v}` + after;
              } else {
                 newLine = before + `_${v}` + after;
              }
            } else {
               newLine = before + `_${v}` + after;
            }
          }
        } else {
          // Standard replacement
          let before = newLine.substring(0, newLine.indexOf(v));
          let after = newLine.substring(newLine.indexOf(v) + v.length);
          newLine = before + `_${v}` + after;
        }
      }
    }

    if (lineStr !== newLine) {
      lines[lineNum - 1] = newLine;
      modified = true;
      fixedCount++;
    } else {
      failedCount++;
    }
  }

  if (modified) {
    fs.writeFileSync(file.filePath, lines.join('\n'), 'utf8');
  }
}

