'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { Input } from '@/components/ui/input';
import { Textarea } from '@/components/ui/textarea';
import { Vote, CheckCircle2, XCircle, Plus, ShieldCheck } from 'lucide-react';
import { toast } from 'sonner';

export default function VotingPage() {
  const [proposals, setProposals] = useState<any[]>([]);
  const [_loading, setLoading] = useState(true);
  const [actionLoading, setActionLoading] = useState(false);
  const [showModal, setShowModal] = useState(false);
  const [newTitle, setNewTitle] = useState('');
  const [newDesc, setNewDesc] = useState('');

  const fetchProposals = async () => {
    try {
      const res = await fetch('/api/admin/voting');
      const data = await res.json();
      setProposals(Array.isArray(data) ? data : []);
    } catch (_err) {
      toast.error('Failed to load proposals');
    } finally {
      setLoading(false);
    }
  };

  useEffect(() => {
    fetchProposals();
  }, []);

  const handleVote = async (proposalId: string, vote: 'YES' | 'NO' | 'ABSTAIN') => {
    setActionLoading(true);
    try {
      const res = await fetch('/api/admin/voting', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ action: 'VOTE', proposalId, vote }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Vote failed');

      toast.success(`Your vote (${vote}) has been recorded on the cooperative ledger!`);
      await fetchProposals();
    } catch (err: any) {
      toast.error(err.message || 'Vote failed');
    } finally {
      setActionLoading(false);
    }
  };

  const handleCreateProposal = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!newTitle.trim() || !newDesc.trim()) return toast.error('Title and description required');

    setActionLoading(true);
    try {
      const res = await fetch('/api/admin/voting', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          action: 'CREATE_PROPOSAL',
          title: newTitle.trim(),
          description: newDesc.trim(),
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Proposal creation failed');

      toast.success('Democratic proposal created successfully!');
      setShowModal(false);
      setNewTitle('');
      setNewDesc('');
      await fetchProposals();
    } catch (err: any) {
      toast.error(err.message || 'Creation failed');
    } finally {
      setActionLoading(false);
    }
  };

  return (
    <div className="space-y-6 p-4 md:p-8 max-w-5xl mx-auto w-full pb-20">
      <div className="flex justify-between items-center">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-3xl font-bold tracking-tight">Cooperative Democratic Governance</h1>
            <Badge className="bg-primary/10 text-primary font-bold">1 Member, 1 Vote</Badge>
          </div>
          <p className="text-sm text-muted-foreground mt-1">
            Democratic decision making on cooperative fee policies, welfare expansions, and wage floors.
          </p>
        </div>
        <Button onClick={() => setShowModal(true)} className="gap-1.5 font-bold">
          <Plus className="h-4 w-4" /> New Proposal
        </Button>
      </div>

      <div className="space-y-4">
        {proposals.length === 0 ? (
          <Card>
            <CardContent className="p-8 text-center text-muted-foreground text-sm">
              No active cooperative proposals right now.
            </CardContent>
          </Card>
        ) : (
          proposals.map((p) => {
            const stats = p.stats || { yesVotes: 0, noVotes: 0, abstainVotes: 0, totalVotes: 0, yesPercent: 50, noPercent: 50 };
            return (
              <Card key={p.id} className="border shadow-xs">
                <CardContent className="p-6 space-y-4 text-xs">
                  <div className="flex justify-between items-start">
                    <div>
                      <h3 className="text-base font-bold text-foreground">{p.title}</h3>
                      <p className="text-muted-foreground mt-0.5">
                        Proposed by {p.createdBy?.name || 'Cooperative Member'} • {p.cooperative?.name || 'Ahmedabad Cooperative'}
                      </p>
                    </div>
                    <Badge variant={p.status === 'OPEN' ? 'default' : 'secondary'}>{p.status}</Badge>
                  </div>

                  <p className="text-sm text-muted-foreground">{p.description}</p>

                  {/* Vote Progress Bar */}
                  <div className="space-y-1.5 pt-2">
                    <div className="flex justify-between text-xs font-semibold text-foreground">
                      <span className="text-green-600">YES: {stats.yesVotes} ({stats.yesPercent}%)</span>
                      <span className="text-destructive">NO: {stats.noVotes} ({stats.noPercent}%)</span>
                    </div>
                    <div className="w-full bg-destructive/20 rounded-full h-3 flex overflow-hidden">
                      <div
                        className="bg-green-600 h-full transition-all duration-300"
                        style={{ width: `${stats.yesPercent}%` }}
                      />
                    </div>
                  </div>

                  {/* Vote Buttons */}
                  <div className="flex items-center justify-between pt-3 border-t">
                    <div className="flex gap-2">
                      <Button
                        size="sm"
                        variant={p.userVote === 'YES' ? 'default' : 'outline'}
                        className="text-green-600 border-green-600 hover:bg-green-50"
                        onClick={() => handleVote(p.id, 'YES')}
                        disabled={actionLoading}
                      >
                        <CheckCircle2 className="h-4 w-4 mr-1.5" /> Vote YES
                      </Button>
                      <Button
                        size="sm"
                        variant={p.userVote === 'NO' ? 'destructive' : 'outline'}
                        className="text-destructive border-destructive hover:bg-destructive/10"
                        onClick={() => handleVote(p.id, 'NO')}
                        disabled={actionLoading}
                      >
                        <XCircle className="h-4 w-4 mr-1.5" /> Vote NO
                      </Button>
                      <Button
                        size="sm"
                        variant={p.userVote === 'ABSTAIN' ? 'secondary' : 'outline'}
                        onClick={() => handleVote(p.id, 'ABSTAIN')}
                        disabled={actionLoading}
                      >
                        Abstain
                      </Button>
                    </div>

                    {p.userVote && (
                      <span className="text-xs font-bold text-primary flex items-center gap-1">
                        <ShieldCheck className="h-4 w-4" /> You voted {p.userVote}
                      </span>
                    )}
                  </div>
                </CardContent>
              </Card>
            );
          })
        )}
      </div>

      {/* New Proposal Modal */}
      {showModal && (
        <div className="fixed inset-0 bg-black/50 z-50 flex items-center justify-center p-4">
          <Card className="w-full max-w-lg bg-card">
            <CardHeader>
              <CardTitle className="text-base flex items-center gap-2">
                <Vote className="h-5 w-5 text-primary" /> Create Cooperative Proposal
              </CardTitle>
            </CardHeader>
            <CardContent>
              <form onSubmit={handleCreateProposal} className="space-y-4 text-xs">
                <div>
                  <label className="font-semibold block mb-1">Proposal Title *</label>
                  <Input
                    required
                    value={newTitle}
                    onChange={(e) => setNewTitle(e.target.value)}
                    placeholder="e.g. Increase Worker Monsoon Tool Allowance"
                  />
                </div>
                <div>
                  <label className="font-semibold block mb-1">Detailed Description & Justification *</label>
                  <Textarea
                    required
                    value={newDesc}
                    onChange={(e) => setNewDesc(e.target.value)}
                    placeholder="Explain the proposed policy change and its impact on members..."
                    className="min-h-[100px]"
                  />
                </div>
                <div className="flex gap-2 pt-2">
                  <Button
                    type="button"
                    variant="outline"
                    className="flex-1"
                    onClick={() => setShowModal(false)}
                  >
                    Cancel
                  </Button>
                  <Button
                    type="submit"
                    className="flex-1 font-bold"
                    disabled={actionLoading}
                  >
                    {actionLoading ? 'Publishing...' : 'Submit Proposal for Voting'}
                  </Button>
                </div>
              </form>
            </CardContent>
          </Card>
        </div>
      )}
    </div>
  );
}

import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { redirect } from 'next/navigation';
import { Card, CardContent, CardHeader, CardTitle, CardDescription } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import { AdminWorkerActions } from './actions';
import { SkillAssessmentActions } from './skill-actions';

export default async function AdminWorkerDetailsPage({ params }: { params: Promise<{ id: string }> | { id: string } }) {
  const session = await auth();
  const userRole = session?.user?.role;
  if (!session?.user || (userRole !== 'ADMIN' && userRole !== 'COOPERATIVE_ADMIN' && userRole !== 'FEDERATION_ADMIN')) redirect('/login');

  const resolvedParams = await params;
  const workerId = resolvedParams?.id;

  const worker = await prisma.worker.findUnique({
    where: { id: workerId },
    include: {
      user: true,
      cooperative: true,
      skills: { include: { skill: true } }
    }
  });

  if (!worker) return <div>Worker not found</div>;

  if (userRole === 'COOPERATIVE_ADMIN' && worker.cooperativeId !== session.user.cooperativeId) {
    return (
      <div className="p-6 max-w-4xl mx-auto">
        <div className="bg-red-50 text-red-600 p-4 rounded-lg">
          Forbidden: This worker belongs to a different cooperative.
        </div>
      </div>
    );
  }

  return (
    <div className="p-6 max-w-4xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">{worker.user.name}</h1>
          <p className="text-gray-500 text-sm">Worker Profile Details</p>
        </div>
        <Badge className="text-sm">
          {worker.verificationStatus}
        </Badge>
      </div>

      <div className="grid grid-cols-1 md:grid-cols-2 gap-6">
        <Card>
          <CardHeader>
            <CardTitle>Personal Information</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <span className="text-xs text-gray-500 uppercase tracking-wider">Email</span>
              <p className="font-medium">{worker.user.email}</p>
            </div>
            <div>
              <span className="text-xs text-gray-500 uppercase tracking-wider">Phone</span>
              <p className="font-medium">{worker.user.phone || 'N/A'}</p>
            </div>
            <div>
              <span className="text-xs text-gray-500 uppercase tracking-wider">Address</span>
              <p className="font-medium">{worker.address}, {worker.city}</p>
            </div>
          </CardContent>
        </Card>

        <Card>
          <CardHeader>
            <CardTitle>Professional Details</CardTitle>
          </CardHeader>
          <CardContent className="space-y-4">
            <div>
              <span className="text-xs text-gray-500 uppercase tracking-wider">Cooperative</span>
              <p className="font-medium">{worker.cooperative?.name || 'None'}</p>
            </div>
            <div>
              <span className="text-xs text-gray-500 uppercase tracking-wider">Primary Trade</span>
              <p className="font-medium">{worker.primaryTrade || 'Not specified'}</p>
            </div>
            <div>
              <span className="text-xs text-gray-500 uppercase tracking-wider">Experience</span>
              <p className="font-medium">{worker.experience} years</p>
            </div>
          </CardContent>
        </Card>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Trade Skills & Verification</CardTitle>
          <CardDescription>Review the worker's declared skills and their current assessment status.</CardDescription>
        </CardHeader>
        <CardContent>
          {worker.skills.length === 0 ? (
            <p className="text-gray-500 text-sm">No skills listed.</p>
          ) : (
            <div className="grid gap-3">
              {worker.skills.map((ws) => (
                <div key={ws.id} className="flex flex-col sm:flex-row justify-between p-3 bg-gray-50 border rounded-lg">
                  <div>
                    <h4 className="font-bold text-gray-900">{ws.skill.name}</h4>
                    <p className="text-sm text-gray-600">
                      Level: {ws.proficiencyLevel} {ws.experienceYears ? `| Exp: ${ws.experienceYears} yrs` : ''}
                    </p>
                    {ws.experienceDescription && (
                      <p className="text-xs text-gray-500 mt-1 italic">"{ws.experienceDescription}"</p>
                    )}
                  </div>
                  <div className="mt-2 sm:mt-0 flex flex-col items-start sm:items-end gap-2">
                    <Badge variant="outline" className={
                      ws.skillVerificationStatus === 'SKILL_ASSESSED' ? 'bg-green-100 text-green-800 border-green-200' :
                      ws.skillVerificationStatus === 'ASSESSMENT_PENDING' ? 'bg-orange-100 text-orange-800 border-orange-200' :
                      ws.skillVerificationStatus === 'REJECTED' ? 'bg-red-100 text-red-800 border-red-200' :
                      'bg-gray-100 text-gray-800 border-gray-200'
                    }>
                      {ws.skillVerificationStatus?.replace('_', ' ') || 'SELF DECLARED'}
                    </Badge>
                    <SkillAssessmentActions workerId={worker.id} skillId={ws.id} currentStatus={ws.skillVerificationStatus} />
                  </div>
                </div>
              ))}
            </div>
          )}
        </CardContent>
      </Card>

      <Card>
        <CardHeader>
          <CardTitle>Verification Actions</CardTitle>
        </CardHeader>
        <CardContent>
          <AdminWorkerActions workerId={worker.id} currentStatus={worker.verificationStatus} />
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { useRouter } from 'next/navigation';
import { CheckCircle2, AlertCircle, XCircle } from 'lucide-react';
import { toast } from 'sonner';

export function SkillAssessmentActions({ workerId, skillId, currentStatus }: { workerId: string, skillId: string, currentStatus: string | null }) {
  const router = useRouter();
  const [loading, setLoading] = useState(false);

  const handleUpdate = async (status: string) => {
    let notes = '';
    if (status === 'REJECTED' || status === 'SKILL_ASSESSED') {
      const input = prompt(`Enter notes for ${status} (optional):`);
      if (input === null) return;
      notes = input;
    }

    setLoading(true);
    try {
      const res = await fetch(`/api/admin/verification`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ 
          workerId,
          action: 'ASSESS_SKILL',
          skillId, 
          status,
          notes 
        }),
      });
      const data = await res.json();
      if (res.ok) {
        toast.success(`Skill status updated to ${status}`);
        router.refresh();
      } else {
        toast.error(data.error || 'Failed to update skill status');
      }
    } catch (e: any) {
      console.error(e);
      toast.error('Error updating status');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex gap-2">
      {currentStatus !== 'SKILL_ASSESSED' && (
        <Button 
          size="sm"
          onClick={() => handleUpdate('SKILL_ASSESSED')} 
          disabled={loading}
          className="bg-green-600 hover:bg-green-700 text-white h-7 text-xs px-2"
        >
          <CheckCircle2 className="w-3.5 h-3.5 mr-1" /> Approve
        </Button>
      )}
      {currentStatus !== 'ASSESSMENT_PENDING' && currentStatus !== 'SKILL_ASSESSED' && (
        <Button 
          size="sm"
          onClick={() => handleUpdate('ASSESSMENT_PENDING')} 
          disabled={loading}
          variant="outline"
          className="text-amber-600 border-amber-200 hover:bg-amber-50 h-7 text-xs px-2"
        >
          <AlertCircle className="w-3.5 h-3.5 mr-1" /> Mark Pending
        </Button>
      )}
      {currentStatus !== 'REJECTED' && (
        <Button 
          size="sm"
          onClick={() => handleUpdate('REJECTED')} 
          disabled={loading}
          variant="destructive"
          className="h-7 text-xs px-2"
        >
          <XCircle className="w-3.5 h-3.5 mr-1" /> Reject
        </Button>
      )}
    </div>
  );
}

import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { redirect } from 'next/navigation';
import { Card, CardContent } from '@/components/ui/card';
import { Badge } from '@/components/ui/badge';
import Link from 'next/link';

export default async function AdminWorkersPage({ searchParams }: { searchParams: Promise<{ status?: string }> | { status?: string } }) {
  const session = await auth();
  const userRole = session?.user?.role;
  if (!session?.user || (userRole !== 'ADMIN' && userRole !== 'COOPERATIVE_ADMIN' && userRole !== 'FEDERATION_ADMIN')) redirect('/login');

  const resolvedParams = await searchParams;
  const statusFilter = resolvedParams?.status || 'ALL';

  const whereClause: any = {};
  if (statusFilter !== 'ALL') whereClause.verificationStatus = statusFilter;
  if (userRole === 'COOPERATIVE_ADMIN' && session.user.cooperativeId) {
    whereClause.cooperativeId = session.user.cooperativeId;
  }

  const workers = await prisma.worker.findMany({
    where: whereClause,
    include: {
      user: { select: { name: true, email: true, phone: true } },
      cooperative: { select: { name: true } },
      skills: { include: { skill: true } }
    },
    orderBy: { joinedAt: 'desc' }
  });

  return (
    <div className="p-6 max-w-7xl mx-auto space-y-6">
      <div className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold text-gray-900">Worker Verification</h1>
          <p className="text-gray-500 text-sm">Review and manage worker accounts.</p>
        </div>
        <div className="flex gap-2">
          <Link href="?status=PENDING" className={`px-4 py-2 rounded-lg text-sm font-semibold ${statusFilter === 'PENDING' ? 'bg-orange-100 text-orange-700' : 'bg-white border text-gray-600'}`}>Pending</Link>
          <Link href="?status=VERIFIED" className={`px-4 py-2 rounded-lg text-sm font-semibold ${statusFilter === 'VERIFIED' ? 'bg-green-100 text-green-700' : 'bg-white border text-gray-600'}`}>Verified</Link>
          <Link href="?status=REJECTED" className={`px-4 py-2 rounded-lg text-sm font-semibold ${statusFilter === 'REJECTED' ? 'bg-red-100 text-red-700' : 'bg-white border text-gray-600'}`}>Rejected</Link>
          <Link href="?status=ALL" className={`px-4 py-2 rounded-lg text-sm font-semibold ${statusFilter === 'ALL' ? 'bg-blue-100 text-blue-700' : 'bg-white border text-gray-600'}`}>All</Link>
        </div>
      </div>

      <div className="grid gap-4">
        {workers.length === 0 ? (
          <div className="p-8 text-center bg-white border rounded-xl">
            <p className="text-gray-500">No workers found with status {statusFilter}.</p>
          </div>
        ) : (
          workers.map(w => (
            <Card key={w.id}>
              <CardContent className="p-4 sm:p-6 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
                <div>
                  <div className="flex items-center gap-2 mb-1">
                    <h3 className="font-bold text-lg">{w.user.name}</h3>
                    <Badge variant="outline" className={
                      w.verificationStatus === 'VERIFIED' ? "text-green-600 border-green-600" :
                      w.verificationStatus === 'PENDING' ? "text-orange-600 border-orange-600" :
