import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import crypto from 'crypto';
import { sendPasswordResetEmail } from '@/lib/email';

export async function POST(req: NextRequest) {
  try {
    const { email } = await req.json();

    if (!email || typeof email !== 'string') {
      return NextResponse.json({ error: 'Valid email is required' }, { status: 400 });
    }

    const normalizedEmail = email.trim().toLowerCase();

    // 1. Look up user
    const user = await prisma.user.findUnique({
      where: { email: normalizedEmail },
    });

    // DO NOT reveal if user exists to prevent account enumeration
    if (!user) {
      return NextResponse.json(
        { message: 'If an account exists for this email, a password reset link has been sent.' },
        { status: 200 }
      );
    }

    // 2. Generate secure random token
    const rawToken = crypto.randomBytes(32).toString('hex');
    const tokenHash = crypto.createHash('sha256').update(rawToken).digest('hex');

    // 3. Expiration: 30 minutes from now
    const expiresAt = new Date(Date.now() + 30 * 60 * 1000);

    // 4. Invalidate previous active tokens for this user
    await prisma.passwordResetToken.updateMany({
      where: {
        userId: user.id,
        usedAt: null,
        expiresAt: { gt: new Date() }, // still active
      },
      data: {
        usedAt: new Date(), // effectively invalidate them by marking as "used" or expired. 
        // We'll just set expiresAt to now
        expiresAt: new Date(),
      },
    });

    // 5. Save hash to DB
    await prisma.passwordResetToken.create({
      data: {
        userId: user.id,
        tokenHash,
        expiresAt,
      },
    });

    // 6. Generate the link
    // Support standard Vercel environment variables or explicit NEXT_PUBLIC_APP_URL
    let baseUrl = process.env.NEXT_PUBLIC_APP_URL || process.env.VERCEL_PROJECT_PRODUCTION_URL || process.env.VERCEL_URL || 'http://localhost:3000';

    // Vercel URLs don't include protocol, so add https:// if missing and not localhost
    if (!baseUrl.startsWith('http')) {
      baseUrl = `https://${baseUrl}`;
    }

    const resetUrl = `${baseUrl}/reset-password?token=${rawToken}`;

    // 7. Send Email
    try {
      await sendPasswordResetEmail(user.email, resetUrl);
    } catch (emailError) {
      console.error('Failed to send reset email:', emailError);
      return NextResponse.json(
        { error: 'An error occurred while sending the reset email. Please try again later.' },
        { status: 500 }
      );
    }

    return NextResponse.json(
      { message: 'If an account exists for this email, a password reset link has been sent.' },
      { status: 200 }
    );
  } catch (error: any) {
    console.error('Forgot Password API error:', error);
    return NextResponse.json(
      { error: 'An unexpected error occurred' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { isValidEmail, isValidPhone, normalizePhone } from '@/lib/validation';

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const { name, type = 'OTHER', email, phone, password, address, city = 'Ahmedabad', contactPerson } = body;

    if (!name || typeof name !== 'string' || name.trim().length === 0) {
      return NextResponse.json({ error: 'Institution name is required' }, { status: 400 });
    }

    if (!contactPerson || typeof contactPerson !== 'string' || contactPerson.trim().length === 0) {
      return NextResponse.json({ error: 'Contact person name is required' }, { status: 400 });
    }

    if (!email || typeof email !== 'string' || !isValidEmail(email)) {
      return NextResponse.json({ error: 'A valid email address is required' }, { status: 400 });
    }

    if (!phone || typeof phone !== 'string' || phone.trim() === '') {
      return NextResponse.json({ error: 'A phone number is required' }, { status: 400 });
    }

    if (!isValidPhone(phone)) {
      return NextResponse.json({ error: 'A valid 10-digit Indian mobile number is required' }, { status: 400 });
    }

    if (!password || typeof password !== 'string' || password.length < 6) {
      return NextResponse.json({ error: 'Password must be at least 6 characters' }, { status: 400 });
    }

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedPhone = normalizePhone(phone);

    // Check if email or phone is already registered
    const existingUser = await prisma.user.findFirst({
      where: {
        OR: [
          { email: normalizedEmail },
          ...(normalizedPhone ? [{ phone: normalizedPhone }] : []),
        ],
      },
    });

    if (existingUser) {
      if (existingUser.email === normalizedEmail) {
        return NextResponse.json({ error: 'An account with this email already exists.' }, { status: 409 });
      } else {
        return NextResponse.json({ error: 'This phone number is already registered.' }, { status: 409 });
      }
    }

    // Secure password hashing
    const passwordHash = await bcrypt.hash(password, 10);

    // Create User, Institution, and InstitutionalCustomer in a transaction
    const user = await prisma.$transaction(async (tx) => {
      const institution = await tx.institution.create({
        data: {
          name: name.trim(),
          type,
          address: address ? address.trim() : 'Location Not Provided',
          city,
          contactPerson: contactPerson.trim(),
          contactPhone: normalizedPhone,
        }
      });

      const newUser = await tx.user.create({
        data: {
          name: contactPerson.trim(),
          email: normalizedEmail,
          phone: normalizedPhone,
          passwordHash,
          role: 'INSTITUTIONAL_CUSTOMER',
          language: 'en',
          institutionalCustomer: {
            create: {
              institutionId: institution.id
            }
          }
        },
        include: {
          institutionalCustomer: true,
        }
      });

      return newUser;
    });

    return NextResponse.json(
      {
        success: true,
        message: 'Institution registered successfully.',
        user: {
          id: user.id,
          name: user.name,
          email: user.email,
          role: user.role,
        },
      },
      { status: 201 }
    );
  } catch (error: any) {
    console.error('Institution Registration Error:', error);
    return NextResponse.json(
      { error: error.message || 'Failed to register institution. Please try again.' },
      { status: 500 }
    );
  }
}

