import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import crypto from 'crypto';
import bcrypt from 'bcryptjs';

export async function POST(req: NextRequest) {
  try {
    const { token, password } = await req.json();

    if (!token || typeof token !== 'string') {
      return NextResponse.json({ error: 'Invalid or missing token' }, { status: 400 });
    }

    if (!password || password.length < 8) {
      return NextResponse.json({ error: 'Password must be at least 8 characters long' }, { status: 400 });
    }

    // 1. Hash the provided raw token to compare with DB
    const tokenHash = crypto.createHash('sha256').update(token).digest('hex');

    // 2. Find the token
    const resetToken = await prisma.passwordResetToken.findUnique({
      where: { tokenHash },
      include: { user: true },
    });

    if (!resetToken) {
      return NextResponse.json({ error: 'This password reset link is invalid.' }, { status: 400 });
    }

    // 3. Check if used
    if (resetToken.usedAt) {
      return NextResponse.json({ error: 'This password reset link has already been used.' }, { status: 400 });
    }

    // 4. Check if expired
    if (resetToken.expiresAt < new Date()) {
      return NextResponse.json({ error: 'This password reset link has expired. Please request a new one.' }, { status: 400 });
    }

    // 5. Hash new password EXACTLY like /api/auth/register
    const passwordHash = await bcrypt.hash(password, 10);

    // 6. Update user and invalidate token
    await prisma.$transaction([
      prisma.user.update({
        where: { id: resetToken.userId },
        data: { passwordHash },
      }),
      prisma.passwordResetToken.update({
        where: { id: resetToken.id },
        data: { usedAt: new Date() },
      }),
      // Invalidate any other active tokens for this user
      prisma.passwordResetToken.updateMany({
        where: {
          userId: resetToken.userId,
          id: { not: resetToken.id },
          usedAt: null,
          expiresAt: { gt: new Date() },
        },
        data: {
          expiresAt: new Date(),
          usedAt: new Date(),
        },
      }),
    ]);

    return NextResponse.json({ message: 'Password reset successfully' }, { status: 200 });
  } catch (error: any) {
    console.error('Reset Password API error:', error);
    return NextResponse.json(
      { error: 'An unexpected error occurred' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { auth } from '@/lib/auth';

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const resolvedParams = await params;
    const bookingId = resolvedParams.id;
    const body = await req.json();
    const { category = 'POOR_QUALITY', description } = body;

    if (!description) {
      return NextResponse.json({ error: 'Description is required' }, { status: 400 });
    }

    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
    });

    if (!booking) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 });
    }

    const sessionUser = session.user;
    const isCustomer = sessionUser.customerId && sessionUser.customerId === booking.customerId;
    const isAdmin = sessionUser.role === 'ADMIN' || sessionUser.role === 'COOPERATIVE_ADMIN';

    if (!isCustomer && !isAdmin) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const customerId = booking.customerId;

    const complaint = await prisma.complaint.create({
      data: {
        bookingId,
        customerId,
        workerId: booking.workerId,
        category,
        description,
        status: 'OPEN',
      },
    });

    return NextResponse.json({ success: true, complaint }, { status: 201 });
  } catch (error: any) {
    console.error('Complaint Error:', error);
    return NextResponse.json({ error: error.message || 'Failed to file complaint' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { auth } from '@/lib/auth';
import { sendNotification } from '@/services/notification';

export async function GET(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const resolvedParams = await params;
    const bookingId = resolvedParams.id;

    const booking = await prisma.booking.findUnique({
      where: { id: bookingId }
    });

    if (!booking) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 });
    }

    const isCustomer = session.user.customerId === booking.customerId;
    const isWorker = session.user.workerId === booking.workerId;
    const isAdmin = ['ADMIN', 'COOPERATIVE_ADMIN', 'FEDERATION_ADMIN'].includes(session.user.role);

    if (!isCustomer && !isWorker && !isAdmin) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const materials = await prisma.materialRequest.findMany({
      where: { bookingId },
      orderBy: { createdAt: 'desc' },
    });

    return NextResponse.json(materials);
  } catch (error: any) {
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const resolvedParams = await params;
    const bookingId = resolvedParams.id;
    const body = await req.json();
    const { item, quantity = 1, unitPrice, receiptUrl } = body;

    if (!item || !unitPrice) {
      return NextResponse.json({ error: 'item name and unitPrice are required' }, { status: 400 });
    }

    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        customer: { include: { user: true } },
        worker: { include: { user: true } },
      },
    });

    if (!booking) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 });
    }

    const workerId = session.user.workerId;
    if (workerId !== booking.workerId) {
      return NextResponse.json({ error: 'Forbidden: Only the assigned worker can request materials' }, { status: 403 });
    }

    const qty = parseInt(quantity.toString()) || 1;
    const price = parseFloat(unitPrice.toString());
    const totalPrice = qty * price;

    const material = await prisma.materialRequest.create({
      data: {
        bookingId,
        workerId,
        item,
        quantity: qty,
        unitPrice: price,
        totalPrice,
        receiptUrl: receiptUrl || null,
        status: 'PENDING',
      },
    });

    // Notify customer
    if (booking.customer?.user?.id) {
      await sendNotification(
        booking.customer.user.id,
        'BOOKING',
        'Material Approval Requested',
        `${booking.worker.user.name} requested approval for replacement part: ${item} (₹${totalPrice}).`,
        { bookingId, materialId: material.id, amount: totalPrice }
      );
    }

    return NextResponse.json(material, { status: 201 });
  } catch (error: any) {
    console.error('Material Request Error:', error);
    return NextResponse.json({ error: error.message || 'Failed to create material request' }, { status: 500 });
  }
}

export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const resolvedParams = await params;
    const bookingId = resolvedParams.id;
    const body = await req.json();
    const { materialId, status } = body; // 'APPROVED' or 'REJECTED'

    if (!materialId || !status) {
      return NextResponse.json({ error: 'materialId and status are required' }, { status: 400 });
    }

    const existingMaterial = await prisma.materialRequest.findUnique({
      where: { id: materialId },
      include: { booking: true },
    });

    if (!existingMaterial || existingMaterial.bookingId !== bookingId) {
      return NextResponse.json({ error: 'Material not found for this booking' }, { status: 404 });
    }

    const isCustomer = session.user.customerId === existingMaterial.booking.customerId;
    const isAdmin = ['ADMIN', 'COOPERATIVE_ADMIN', 'FEDERATION_ADMIN'].includes(session.user.role);

    if (!isCustomer && !isAdmin) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    const updated = await prisma.materialRequest.update({
      where: { id: materialId },
      data: {
        status: status.toUpperCase() === 'APPROVED' ? 'APPROVED' : 'REJECTED',
        approvedAt: status.toUpperCase() === 'APPROVED' ? new Date() : null,
      },
      include: {
        booking: {
          include: {
            worker: { include: { user: true } },
          },
        },
      },
    });

    // Notify worker
    if (updated.booking.worker?.user?.id) {
      await sendNotification(
        updated.booking.worker.user.id,
        'BOOKING',
        `Material ${status.toUpperCase() === 'APPROVED' ? 'Approved' : 'Rejected'}`,
        `Customer has ${status.toLowerCase()} material request: ${updated.item} (₹${updated.totalPrice}).`,
        { bookingId, materialId: updated.id, status }
      );
    }

    return NextResponse.json(updated);
  } catch (error: any) {
    console.error('Material Approval Error:', error);
    return NextResponse.json({ error: error.message || 'Failed to update material request' }, { status: 500 });
  }
}

