export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const resolvedParams = await params;
    const bookingId = resolvedParams.id;
    const body = await req.json();
    const { type = 'BEFORE', imageUrl, caption, latitude, longitude } = body;

    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
    });

    if (!booking) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 });
    }

    const u = session.user;
    const isCustomer = u.customerId === booking.customerId;
    const isWorker = u.workerId === booking.workerId;
    const isAdmin = ['ADMIN', 'COOPERATIVE_ADMIN'].includes(u.role);

    const isBefore = type.toUpperCase() === 'BEFORE';
    const isAfter = type.toUpperCase() === 'AFTER';

    if (isBefore && !isCustomer && !isAdmin) {
      return NextResponse.json({ error: 'Forbidden: Only the customer can upload BEFORE photos' }, { status: 403 });
    }

    if (isAfter && !isWorker && !isAdmin) {
      return NextResponse.json({ error: 'Forbidden: Only the worker can upload AFTER photos' }, { status: 403 });
    }

    if (!isBefore && !isAfter) {
      return NextResponse.json({ error: 'Invalid photo type' }, { status: 400 });
    }

    const proof = await prisma.jobProof.create({
      data: {
        bookingId,
        workerId: booking.workerId, // Ensure it is linked to the booking's worker
        type: isAfter ? 'AFTER' : 'BEFORE',
        imageUrl: imageUrl,
        caption: caption || `${isAfter ? 'AFTER' : 'BEFORE'} service verification photo`,
        latitude: latitude ? parseFloat(latitude) : booking.latitude,
        longitude: longitude ? parseFloat(longitude) : booking.longitude,
      },
    });

    return NextResponse.json(proof, { status: 201 });
  } catch (error: any) {
    console.error('Job Proof Error:', error);
    return NextResponse.json({ error: error.message || 'Failed to save job proof' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { auth } from '@/lib/auth';
import { sendNotification } from '@/services/notification';

export async function POST(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const resolvedParams = await params;
    const bookingId = resolvedParams.id;
    const body = await req.json();
    const {
      technicalQuality = 5,
      punctuality = 5,
      communication = 5,
      professionalism = 5,
      priceTransparency = 5,
      overall,
      review,
    } = body;

    const booking = await prisma.booking.findUnique({
      where: { id: bookingId },
      include: {
        worker: { include: { user: true } },
        customer: true,
      },
    });

    if (!booking) {
      return NextResponse.json({ error: 'Booking not found' }, { status: 404 });
    }

    // 1. Prevent reviewing an uncompleted job
    if (booking.status !== 'COMPLETED') {
      return NextResponse.json(
        { error: 'Reviews can only be submitted for completed jobs' },
        { status: 400 }
      );
    }

    // 2. Prevent reviewing a job that does not belong to this customer
    const sessionCustomerId = session.user.customerId;
    if (!sessionCustomerId || sessionCustomerId !== booking.customerId) {
      return NextResponse.json(
        { error: 'Unauthorized: You can only review your own bookings' },
        { status: 403 }
      );
    }

    // 3. Prevent duplicate review for the same booking
    const existingRating = await prisma.rating.findUnique({
      where: { bookingId },
    });
    if (existingRating) {
      return NextResponse.json(
        { error: 'A review has already been submitted for this booking' },
        { status: 400 }
      );
    }

    const customerId = booking.customerId;
    const computedScore = overall !== undefined && overall !== null
      ? parseFloat(overall.toString())
      : ((Number(technicalQuality) + Number(punctuality) + Number(communication) + Number(professionalism) + Number(priceTransparency)) / 5);
    const overallScore = Number(Math.max(1, Math.min(5, computedScore)).toFixed(1));

    const cleanedReview = typeof review === 'string' && review.trim().length > 0 ? review.trim() : null;

    const rating = await prisma.rating.create({
      data: {
        bookingId,
        customerId,
        workerId: booking.workerId,
        technicalQuality: Math.max(1, Math.min(5, parseInt(technicalQuality.toString(), 10))),
        punctuality: Math.max(1, Math.min(5, parseInt(punctuality.toString(), 10))),
        communication: Math.max(1, Math.min(5, parseInt(communication.toString(), 10))),
        professionalism: Math.max(1, Math.min(5, parseInt(professionalism.toString(), 10))),
        priceTransparency: Math.max(1, Math.min(5, parseInt(priceTransparency.toString(), 10))),
        overall: overallScore,
        review: cleanedReview,
      },
    });

    // Recompute worker average rating
    const allRatings = await prisma.rating.findMany({
      where: { workerId: booking.workerId },
      select: { overall: true },
    });
    const avg = allRatings.reduce((sum, r) => sum + r.overall, 0) / allRatings.length;

    await prisma.worker.update({
      where: { id: booking.workerId },
      data: {
        averageRating: Number(avg.toFixed(2)),
      },
    });

    if (booking.worker?.user?.id) {
      await sendNotification(
        booking.worker.user.id,
        'RATING',
        'New Customer Rating',
        `You received a ${overallScore}★ rating for Booking #${booking.id.slice(0, 8)}.`,
        { bookingId, rating: overallScore }
      );
    }

    return NextResponse.json({ success: true, rating }, { status: 201 });
  } catch (error: any) {
    console.error('Rating Error:', error);
    return NextResponse.json({ error: error.message || 'Failed to submit rating' }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import { auth } from '@/lib/auth';
import { createBooking } from '@/services/booking';


export async function GET(req: NextRequest) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const customerId = session.user.customerId;
    const workerId = session.user.workerId;
    const role = session.user.role;

    const whereClause: any = {};
    if (role === 'CUSTOMER' && customerId) {
      whereClause.customerId = customerId;
    } else if ((role === 'WORKER' || role === 'HELPER') && workerId) {
      whereClause.workerId = workerId;
    } else if (role === 'COOPERATIVE_ADMIN') {
      const cooperativeId = session.user.cooperativeId;
      if (cooperativeId) {
        whereClause.worker = { cooperativeId };
      }
    }

    const { searchParams } = new URL(req.url);
    const status = searchParams.get('status');
    if (status) {
      whereClause.status = status;
    }

    const bookings = await prisma.booking.findMany({
      where: whereClause,
      include: {
        category: true,
        worker: {
          include: {
            user: { select: { id: true, name: true, phone: true, avatar: true } },
            cooperative: true,
          },
        },
        customer: {
          include: {
            user: { select: { id: true, name: true, phone: true } },
          },
        },
        payment: true,
        invoice: true,
        rating: true,
      },
      orderBy: { createdAt: 'desc' },
    });

    return NextResponse.json(bookings);
  } catch (error: any) {
    console.error('Bookings GET Error:', error);
    return NextResponse.json({ error: error.message || 'Failed to fetch bookings' }, { status: 500 });
  }
}

export async function POST(req: NextRequest) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ success: false, error: 'Unauthorized', code: 'UNAUTHORIZED' }, { status: 401 });
    }

    const body = await req.json();
    let customerId = session.user.customerId;
    if (!customerId) {
      // Find or create customer record for this user
      console.time('[booking] customer lookup');
      const customer = await prisma.customer.findUnique({
        where: { userId: session.user.id },
      });
      console.timeEnd('[booking] customer lookup');
      if (customer) {
        customerId = customer.id;
      } else {
        const newCustomer = await prisma.customer.create({
          data: {
            userId: session.user.id || 'default-user',
            city: body.city || 'Unspecified',
            state: body.state || 'Unspecified',
          },
        });
        customerId = newCustomer.id;
      }
    }

    const {
      workerId,
      categoryId,
      description,
      scheduledDate,
      scheduledTime,
      estimatedPrice,
      address,
      latitude,
      longitude,
      isEmergency,
    } = body;

    if (!workerId || !categoryId) {
      return NextResponse.json({ success: false, error: 'workerId and categoryId are required', code: 'MISSING_FIELDS' }, { status: 400 });
    }

    // Removed ensureServiceCategories() from the hot path to avoid 10 sequential upserts on every booking

    console.time('[booking] category check');
    const categoryExists = await prisma.serviceCategory.findUnique({
      where: { id: categoryId }
    });
    console.timeEnd('[booking] category check');
    
    if (!categoryExists) {
      return NextResponse.json({ success: false, error: 'Selected service category is no longer available. Please select another service.', code: 'INVALID_CATEGORY' }, { status: 400 });
    }

    if (!customerId) {
      return NextResponse.json({ success: false, error: 'Could not resolve customer ID', code: 'CUSTOMER_MISSING' }, { status: 400 });
    }

    const reqId = Math.random().toString(36).substring(7);
    console.time(`[booking] createBooking function ${reqId}`);
    const booking = await createBooking({
      customerId,
      workerId,
      categoryId,
      description: description || 'Service booking',
      scheduledDate: scheduledDate ? new Date(scheduledDate) : new Date(),
      scheduledTime: scheduledTime || '10:00 AM',
      estimatedPrice: estimatedPrice ? parseFloat(estimatedPrice) : 350,
      address: address || 'Service Location Not Provided',
      latitude: latitude ? parseFloat(latitude) : undefined,
      longitude: longitude ? parseFloat(longitude) : undefined,
      isEmergency: !!isEmergency,
    });
    console.timeEnd(`[booking] createBooking function ${reqId}`);

    if (address && customerId) {
      try {
        const normalizedAddress = address.toLowerCase().trim();
        const existingLocations = await prisma.customerLocation.findMany({ where: { customerId } });
        const duplicate = existingLocations.find(l => l.address.toLowerCase().trim() === normalizedAddress);
        if (!duplicate) {
          await prisma.customerLocation.create({
            data: {
              customerId,
              address: address,
              city: body.city || 'Ahmedabad',
              state: body.state || 'Gujarat',
              latitude: latitude ? parseFloat(latitude) : null,
              longitude: longitude ? parseFloat(longitude) : null,
              isDefault: existingLocations.length === 0
            }
          });
        }
      } catch (locErr) {
        console.error('Failed to save customer location history:', locErr);
      }
    }

    const imageUrls = body.imageUrls;
    if (imageUrls && Array.isArray(imageUrls) && imageUrls.length > 0) {
      await prisma.jobProof.createMany({
        data: imageUrls.map((url: string) => ({
          bookingId: booking.id,
          workerId: booking.workerId,
          type: 'BEFORE',
          imageUrl: url,
          caption: 'Customer uploaded BEFORE photo during booking',
          latitude: latitude ? parseFloat(latitude) : undefined,
          longitude: longitude ? parseFloat(longitude) : undefined,
        }))
      });
    }

    return NextResponse.json({ success: true, booking }, { status: 201 });
  } catch (error: any) {
    console.error('Booking Creation Error:', error);
    
    let errorCode = 'INTERNAL_ERROR';
    let status = 500;
    if (error.message === 'Worker not found') { errorCode = 'WORKER_NOT_FOUND'; status = 404; }
    if (error.message.includes('not currently eligible')) { errorCode = 'WORKER_UNAVAILABLE'; status = 403; }
    if (error.message.includes('no longer available for the selected time')) { errorCode = 'SCHEDULING_CONFLICT'; status = 409; }
    
    return NextResponse.json({ success: false, error: error.message || 'Failed to create booking', code: errorCode }, { status });
  }
}

import { NextRequest, NextResponse } from 'next/server';
