export async function PATCH(req: NextRequest) {
  try {
    const session = await auth();
    if (!session?.user?.id) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    // Fallback to empty object if body is missing or invalid JSON
    const body = await req.json().catch(() => ({}));
    const { notificationId, markAll = false } = body;

    if (markAll) {
      await prisma.notification.updateMany({
        where: { userId: session.user.id, readAt: null },
        data: { readAt: new Date() },
      });
      return NextResponse.json({ success: true, message: 'All notifications marked as read' });
    }

    if (notificationId) {
      const existing = await prisma.notification.findUnique({ where: { id: notificationId } });
      if (!existing || existing.userId !== session.user.id) {
        return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
      }

      await prisma.notification.update({
        where: { id: notificationId },
        data: { readAt: new Date() },
      });
      return NextResponse.json({ success: true, message: 'Notification marked as read' });
    }

    return NextResponse.json({ error: 'notificationId or markAll is required' }, { status: 400 });
  } catch (error: any) {
    console.error('Notifications PATCH Error:', error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from "next/server";
import { auth } from "@/lib/auth";
import { createOrganizationLocation } from "@/services/organization";

export async function POST(req: NextRequest) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: "Unauthorized" }, { status: 401 });
    }

    const role = session.user.role;
    const isSociety = role === "SOCIETY_ADMIN";
    const isInstitution = role === "INSTITUTIONAL_CUSTOMER";

    if (!isSociety && !isInstitution) {
      return NextResponse.json({ error: "Forbidden" }, { status: 403 });
    }

    const organizationId = isSociety 
      ? session.user.societyId
      : session.user.institutionId;

    if (!organizationId) {
      return NextResponse.json({ error: "No organization linked" }, { status: 400 });
