export async function PATCH(
  req: NextRequest,
  { params }: { params: Promise<{ id: string }> | { id: string } }
) {
  try {
    const session = await auth();
    if (!session?.user) {
      return NextResponse.json({ error: 'Unauthorized' }, { status: 401 });
    }

    const resolvedParams = await params;
    const workerId = resolvedParams.id;

    const u = session.user;
    const isOwner = u.workerId === workerId;
    const isAdmin = u.role === 'ADMIN' || u.role === 'COOPERATIVE_ADMIN';
    if (!isOwner && !isAdmin) {
      return NextResponse.json({ error: 'Forbidden' }, { status: 403 });
    }

    if (u.role === 'COOPERATIVE_ADMIN') {
      const worker = await prisma.worker.findUnique({ where: { id: workerId } });
      if (!worker) return NextResponse.json({ error: 'Worker not found' }, { status: 404 });
      if (worker.cooperativeId !== u.cooperativeId) {
        return NextResponse.json({ error: 'Forbidden: Worker belongs to a different cooperative' }, { status: 403 });
      }
    }

    const body = await req.json();
    const {
      availabilityStatus,
      serviceRadius,
      bio,
      isEmergencyAvailable,
      workingHoursStart,
      workingHoursEnd,
      // BUG FIX: latitude/longitude were never accepted here, so a worker had no
      // way to set or correct their base location from their profile. That left
      // matchWorkers()/findNearbyWorkers() with no coordinates to compare against,
      // so the worker could never appear in "nearby" results.
      latitude,
      longitude,
      address,
      city,
      state,
    } = body;

    const updated = await prisma.worker.update({
      where: { id: workerId },
      data: {
        ...(availabilityStatus ? { availabilityStatus } : {}),
        ...(serviceRadius !== undefined ? { serviceRadius: parseFloat(serviceRadius.toString()) } : {}),
        ...(bio !== undefined ? { bio } : {}),
        ...(isEmergencyAvailable !== undefined ? { isEmergencyAvailable: !!isEmergencyAvailable } : {}),
        ...(workingHoursStart ? { workingHoursStart } : {}),
        ...(workingHoursEnd ? { workingHoursEnd } : {}),
        ...(typeof latitude === 'number' && !isNaN(latitude) && latitude >= -90 && latitude <= 90 ? { latitude } : {}),
        ...(typeof longitude === 'number' && !isNaN(longitude) && longitude >= -180 && longitude <= 180 ? { longitude } : {}),
        ...(typeof address === 'string' ? { address: address.trim() } : {}),
        ...(typeof city === 'string' ? { city: city.trim() } : {}),
        ...(typeof state === 'string' ? { state: state.trim() } : {}),
      },
    });

    return NextResponse.json(updated);
  } catch (error: any) {
    console.error('Worker Update Error:', error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';
import bcrypt from 'bcryptjs';
import { isValidEmail, isValidPhone, normalizePhone } from '@/lib/validation';

export async function POST(req: NextRequest) {
  try {
    const body = await req.json();
    const {
      name,
      email,
      phone,
      password,
      primaryTrade,
      experience = 1,
      cooperativeId,
      skillIds = [],
      address,
      city = 'Unspecified',
      state = 'Unspecified',
      isEmergencyAvailable = false,
      role = 'WORKER',
      latitude: providedLatitude,
      longitude: providedLongitude,
    } = body;

    if (!name || typeof name !== 'string' || name.trim().length === 0) {
      return NextResponse.json({ error: 'Full legal name is required' }, { status: 400 });
    }

    if (!email || typeof email !== 'string' || !isValidEmail(email)) {
      return NextResponse.json({ error: 'A valid email address is required' }, { status: 400 });
    }
    
    if (!phone || typeof phone !== 'string' || !isValidPhone(phone)) {
      return NextResponse.json({ error: 'A valid 10-digit Indian phone number is required for workers' }, { status: 400 });
    }

    if (!password || typeof password !== 'string' || password.length < 6) {
      return NextResponse.json({ error: 'Password must be at least 6 characters' }, { status: 400 });
    }

    if (!primaryTrade || typeof primaryTrade !== 'string') {
      return NextResponse.json({ error: 'Primary trade selection is required' }, { status: 400 });
    }

    const normalizedEmail = email.trim().toLowerCase();
    const normalizedPhone = normalizePhone(phone);

    // Check existing email
    const existing = await prisma.user.findFirst({
      where: {
        OR: [
          { email: normalizedEmail },
          { phone: normalizedPhone },
        ],
      },
    });
    if (existing) {
      if (existing.email === normalizedEmail) {
        return NextResponse.json({ error: 'An account with this email already exists.' }, { status: 409 });
      } else {
        return NextResponse.json({ error: 'This phone number is already registered.' }, { status: 409 });
      }
    }

    const passwordHash = await bcrypt.hash(password, 10);

    // BUG FIX: worker registration used to hardcode latitude/longitude to null,
    // so a real worker's address was never converted into coordinates. That meant
    // the worker could never be found by proximity-based matching (matchWorkers /
    // findNearbyWorkers both require non-null lat/lng), no matter how close they
    // actually were to a customer. Prefer coordinates the client already has
    // (e.g. from browser geolocation); otherwise geocode the typed address here.
    let latitude: number | null =
      typeof providedLatitude === 'number' && !isNaN(providedLatitude) && providedLatitude >= -90 && providedLatitude <= 90 ? providedLatitude : null;
    let longitude: number | null =
      typeof providedLongitude === 'number' && !isNaN(providedLongitude) && providedLongitude >= -180 && providedLongitude <= 180 ? providedLongitude : null;

    if ((latitude === null || longitude === null) && address && typeof address === 'string' && address.trim()) {
      try {
        const geoRes = await fetch(
          `https://nominatim.openstreetmap.org/search?q=${encodeURIComponent(address.trim())}&format=json&limit=1`,
          { headers: { 'User-Agent': 'CoopConnect/1.0' } }
        );
        const geoData = await geoRes.json();
        if (Array.isArray(geoData) && geoData.length > 0) {
          const fetchedLat = parseFloat(geoData[0].lat);
          const fetchedLng = parseFloat(geoData[0].lon);
          if (!isNaN(fetchedLat) && fetchedLat >= -90 && fetchedLat <= 90) {
            latitude = fetchedLat;
          }
          if (!isNaN(fetchedLng) && fetchedLng >= -180 && fetchedLng <= 180) {
            longitude = fetchedLng;
          }
        }
      } catch (geoError) {
        console.error('Worker registration geocoding failed:', geoError);
        // Non-fatal: worker is created with null coordinates and can set/fix
        // their location later from their profile (see PATCH /api/workers/[id]).
      }
    }

    // Pick first active cooperative if not provided
    let coopId = cooperativeId;
    if (!coopId) {
      const defaultCoop = await prisma.cooperative.findFirst({ where: { isActive: true } });
      coopId = defaultCoop?.id || null;
    }

    const userRole = role === 'HELPER' ? 'HELPER' : 'WORKER';

    const user = await prisma.user.create({
      data: {
        name: name.trim(),
        email: normalizedEmail,
        phone: normalizedPhone,
        passwordHash,
        role: userRole,
        language: 'en',
        worker: {
          create: {
            cooperativeId: coopId,
            primaryTrade: primaryTrade.trim(),
            experience: parseInt(experience.toString(), 10) || 1,
            address: address && typeof address === 'string' ? address.trim() : 'Location Not Provided',
            city,
            state,
            verificationStatus: 'PENDING', // Real worker starts as PENDING until verified by cooperative admin
            availabilityStatus: 'OFFLINE',
            isEmergencyAvailable: !!isEmergencyAvailable,
            totalJobs: 0,
            averageRating: 0,
            completionRate: 100,
            punctualityScore: 100,
            latitude,
            longitude,
            skills: {
              create: Array.isArray(skillIds) ? skillIds.map(sId => ({
                skillId: sId,
                proficiencyLevel: 'INTERMEDIATE',
                verified: false,
                skillVerificationStatus: 'SELF_DECLARED',
              })) : []
            }
          },
        },
      },
      include: {
        worker: true,
      },
    });

    return NextResponse.json(
      {
        success: true,
        message: 'Worker registered successfully. Your profile is pending verification by cooperative admin.',
        user: { id: user.id, name: user.name, email: user.email, role: user.role },
        worker: { id: user.worker?.id, verificationStatus: user.worker?.verificationStatus },
      },
      { status: 201 }
    );
  } catch (error: any) {
    console.error('Worker Registration Error:', error);
    return NextResponse.json(
      { error: error.message || 'Worker registration failed. Please try again.' },
      { status: 500 }
    );
  }
}

import { NextRequest, NextResponse } from 'next/server';
import { prisma } from '@/lib/prisma';

import { auth } from '@/lib/auth';

export async function GET(req: NextRequest) {
  try {
    const session = await auth();
    const { searchParams } = new URL(req.url);
    const categoryId = searchParams.get('categoryId');
    const trade = searchParams.get('trade');
    const cooperativeId = searchParams.get('cooperativeId');
    let status = searchParams.get('status') || 'VERIFIED';

    const u = session?.user;
    const isAdmin = u?.role === 'ADMIN' || u?.role === 'COOPERATIVE_ADMIN';
    if (!session || !isAdmin) {
      status = 'VERIFIED';
    }
    const emergency = searchParams.get('emergency');

    const workers = await prisma.worker.findMany({
      where: {
        ...(status !== 'ALL' ? { verificationStatus: status } : {}),
        ...(cooperativeId ? { cooperativeId } : {}),
        ...(trade ? { primaryTrade: { contains: trade, mode: 'insensitive' } } : {}),
        ...(emergency === 'true' ? { isEmergencyAvailable: true } : {}),
        ...(categoryId
          ? {
              skills: {
                some: {
                  skill: { categoryId },
                },
              },
            }
          : {}),
      },
      include: {
        user: { select: { id: true, name: true, phone: true, avatar: true } },
        cooperative: true,
        skills: { include: { skill: true } },
        certifications: { include: { certification: true } },
      },
      orderBy: { averageRating: 'desc' },
      take: 50,
    });

    return NextResponse.json(workers);
  } catch (error: any) {
    console.error('Workers GET Error:', error);
    return NextResponse.json({ error: error.message }, { status: 500 });
  }
}

import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { redirect } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { MapPin, AlertTriangle } from "lucide-react";
import { findWorkersForOrganizationRequest, assignWorkerToOrganizationRequest } from "@/services/organization";
import { revalidatePath } from "next/cache";

export default async function CooperativeRequestMatchPage({ 
  params 
}: { 
  params: { type: string, id: string } 
}) {
  const session = await auth();

  if (!session?.user || session.user.role !== "COOPERATIVE_ADMIN") {
    redirect("/login");
  }

  const admin = await prisma.cooperativeAdmin.findUnique({
    where: { userId: session.user.id },
  });

  if (!admin) redirect("/login");

  const type = params.type.toUpperCase() as "SOCIETY" | "INSTITUTION";
  const requestId = params.id;

  let request: any;

  if (type === "SOCIETY") {
    request = await prisma.societyServiceRequest.findUnique({
      where: { id: requestId, cooperativeId: admin.cooperativeId },
      include: {
        society: true,
        location: true,
        category: true,
        bookings: {
          include: { worker: { include: { user: true } } }
        }
      }
    });
  } else {
    request = await prisma.institutionServiceRequest.findUnique({
      where: { id: requestId, cooperativeId: admin.cooperativeId },
      include: {
        institution: true,
        location: true,
        category: true,
        bookings: {
          include: { worker: { include: { user: true } } }
        }
      }
    });
  }

  if (!request) {
    return <div className="p-8 text-center text-red-500">Request not found or access denied.</div>;
  }

  const orgName = type === "SOCIETY" ? request.society.name : request.institution.name;

  // Find workers if still open
  let matches: any[] = [];
  let error = "";
  if (request.status === "OPEN") {
    try {
      matches = await findWorkersForOrganizationRequest(requestId, type, request.priority as 'NORMAL' | 'URGENT' | 'EMERGENCY');
      // Filter for this cooperative only
      matches = matches.filter(m => m.worker.cooperativeId === admin.cooperativeId);
    } catch (e: any) {
      error = e.message;
    }
  }

  async function handleAssign(formData: FormData) {
    "use server";
    const workerId = formData.get("workerId") as string;
    if (!workerId) return;

    try {
      const formSession = await auth();
      if (!formSession?.user) throw new Error("Unauthorized");

      await assignWorkerToOrganizationRequest({
        requestId,
        type,
        workerId,
        assignedByUserId: formSession.user.id as string,
      });
      revalidatePath(`/cooperative/requests/${type.toLowerCase()}/${requestId}`);
    } catch (e: any) {
      console.error(e);
      // Handle error gracefully in real app
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Request #{request.id.slice(-6)}</h2>
          <p className="text-muted-foreground">From {orgName}</p>
        </div>
        <Badge variant={request.status === "OPEN" ? "destructive" : "default"} className="text-sm px-3 py-1">
          {request.status}
        </Badge>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Request Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid md:grid-cols-2 gap-4">
            <div>
              <p className="text-sm font-medium text-muted-foreground">Title</p>
              <p>{request.title}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-muted-foreground">Category</p>
              <p>{request.category?.name || "N/A"}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-muted-foreground">Description</p>
              <p className="text-sm">{request.description}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-muted-foreground">Location</p>
              <p className="flex items-center gap-1 text-sm">
                <MapPin className="w-4 h-4 text-muted-foreground" />
                {request.location?.name || request.area}
              </p>
            </div>
          </div>
        </CardContent>
      </Card>

      {request.status === "OPEN" && (
        <div className="space-y-4">
          <h3 className="text-xl font-semibold">Available Workers from your Cooperative</h3>
          {error && <div className="p-4 bg-red-500/10 text-red-500 rounded-lg">{error}</div>}

          <div className="grid gap-4 md:grid-cols-2">
            {matches.map((match, i) => (
              <Card key={match.worker.id} className={i === 0 ? "border-amber-500 shadow-md" : ""}>
                <CardContent className="p-4 flex flex-col h-full">
                  <div className="flex justify-between items-start mb-2">
                    <div className="font-semibold">{match.worker.user.name}</div>
                    <Badge variant="outline">Score: {match.match_score}</Badge>
                  </div>

                  <div className="space-y-2 text-sm mb-4 flex-1">
                    <p className="text-muted-foreground">{match.worker.primaryTrade}</p>
                    <p className="text-xs">{match.explanation}</p>
                  </div>

                  <form action={handleAssign} className="w-full mt-auto">
                    <input type="hidden" name="workerId" value={match.worker.id} />
                    <Button type="submit" className="w-full" variant={i === 0 ? "default" : "secondary"}>
                      Assign this worker
                    </Button>
                  </form>
                </CardContent>
              </Card>
            ))}
            {matches.length === 0 && !error && (
              <div className="col-span-full p-8 text-center border rounded-lg border-dashed">
                <AlertTriangle className="w-8 h-8 mx-auto text-amber-500 mb-2" />
                <p className="font-medium">No eligible workers found</p>
                <p className="text-sm text-muted-foreground">Try adjusting workers' availability or wait for more workers to join.</p>
              </div>
            )}
          </div>
        </div>
      )}

      {request.status !== "OPEN" && request.bookings?.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Assigned Worker</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex items-center gap-4">
              <div className="w-12 h-12 bg-secondary rounded-full flex items-center justify-center">
                {request.bookings[0].worker.user.name.charAt(0)}
              </div>
              <div>
                <p className="font-semibold">{request.bookings[0].worker.user.name}</p>
                <p className="text-sm text-muted-foreground">Booking Status: {request.bookings[0].status}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { redirect } from "next/navigation";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { MapPin, Star } from "lucide-react";

export const metadata = {
  title: "Workers - Cooperative - Co-opConnect",
};

export default async function CooperativeWorkersPage() {
  const session = await auth();

  if (!session?.user || session.user.role !== "COOPERATIVE_ADMIN") {
    redirect("/login");
  }

  const admin = await prisma.cooperativeAdmin.findUnique({
    where: { userId: session.user.id },
  });

  if (!admin) {
    redirect("/login");
  }

  const workers = await prisma.worker.findMany({
    where: { cooperativeId: admin.cooperativeId },
    include: {
      user: true,
      skills: {
        include: { skill: true }
      }
    },
    orderBy: { joinedAt: "desc" }
  });

  return (
    <div className="space-y-6">
      <div>
        <h2 className="text-2xl font-bold tracking-tight">Cooperative Workers</h2>
        <p className="text-muted-foreground">Manage and view all workers in your cooperative.</p>
      </div>

      <div className="grid gap-4 md:grid-cols-2 lg:grid-cols-3">
        {workers.map(worker => (
          <Card key={worker.id} className="overflow-hidden">
            <CardContent className="p-6">
              <div className="flex items-start justify-between">
                <div className="flex items-center gap-3">
                  <div className="w-12 h-12 bg-secondary rounded-full overflow-hidden flex items-center justify-center">
                    {worker.user.avatar ? (
                      <img src={worker.user.avatar} alt={worker.user.name} className="w-full h-full object-cover" />
                    ) : (
                      <span className="text-lg font-medium">{worker.user.name.charAt(0)}</span>
                    )}
                  </div>
                  <div>
                    <h3 className="font-semibold">{worker.user.name}</h3>
                    <p className="text-sm text-muted-foreground">{worker.primaryTrade || "Multi-skilled"}</p>
                  </div>
                </div>
                <Badge variant={worker.availabilityStatus === "AVAILABLE" ? "default" : "secondary"}>
                  {worker.availabilityStatus}
                </Badge>
              </div>

              <div className="mt-4 space-y-2 text-sm">
                <div className="flex items-center gap-2 text-muted-foreground">
                  <MapPin className="w-4 h-4" />
                  <span>{worker.address || worker.city}</span>
                </div>
                <div className="flex items-center gap-2 text-muted-foreground">
                  <Star className="w-4 h-4 text-amber-400 fill-amber-400" />
                  <span>{worker.averageRating.toFixed(1)} ({worker.totalJobs} jobs)</span>
                </div>
              </div>

              <div className="mt-4">
                <div className="flex flex-wrap gap-1">
                  {worker.skills.slice(0, 3).map(ws => (
                    <Badge key={ws.id} variant="outline" className="text-xs font-normal">
                      {ws.skill.name}
                    </Badge>
                  ))}
                  {worker.skills.length > 3 && (
                    <Badge variant="outline" className="text-xs font-normal">
                      +{worker.skills.length - 3} more
                    </Badge>
                  )}
                </div>
              </div>
            </CardContent>
          </Card>
        ))}

        {workers.length === 0 && (
          <div className="col-span-full py-12 text-center text-muted-foreground">
            No workers found in this cooperative.
          </div>
        )}
      </div>
    </div>
  );
}

