import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { notFound, redirect } from 'next/navigation';
import { BookingTimeline } from '@/components/shared/booking-timeline';
import { ServicePinDisplay } from '@/components/shared/service-pin-display';
import { ProofGallery } from '@/components/shared/proof-gallery';
import { InvoiceView } from '@/components/shared/invoice-view';
import { PaymentSummary } from '@/components/shared/payment-summary';
import { RatingInput } from '@/components/shared/rating-input';
import { MaterialApproval } from '@/components/shared/material-approval';
import { WorkerCard } from '@/components/shared/worker-card';
import { CustomerBookingActions } from '@/components/customer/customer-booking-actions';
import { RealtimeBookingListener } from '@/components/shared/realtime-listeners';
import { LiveMap } from '@/components/shared/live-map';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { Map, ShieldCheck } from 'lucide-react';
import Link from 'next/link';
import { SOSButton } from '@/components/safety/SOSButton';

export default async function BookingDetailPage({ params }: { params: Promise<{ id: string }> | { id: string } }) {
  const session = await auth();

  if (!session || !session.user) {
    redirect('/login');
  }

  const resolvedParams = await params;
  const bookingId = resolvedParams.id;

  const booking = await prisma.booking.findUnique({
    where: { id: bookingId },
    include: {
      category: true,
      worker: {
        include: {
          user: true,
          cooperative: true,
        },
      },
      materialRequests: true,
      invoice: {
        include: {
          items: true,
        },
      },
      jobProofs: true,
      rating: true,
      payment: true,
      warranty: true,
      statusHistory: {
        orderBy: { createdAt: 'asc' },
      },
    },
  });

  if (!booking) notFound();

  const isCompleted = booking.status === 'COMPLETED';
  const showPin = ['ACCEPTED', 'TRAVELLING', 'ARRIVED'].includes(booking.status);
  const isTravelling = booking.status === 'TRAVELLING';
  const isCancellable = !isCompleted && booking.status !== 'CANCELLED';

  return (
    <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-3xl mx-auto w-full">
      <RealtimeBookingListener userId={session.user?.id as string} role="customer" />

      <header className="flex justify-between items-start">
        <div>
          <div className="flex items-center gap-2">
            <h1 className="text-2xl font-bold tracking-tight">Booking #{booking.id.slice(0, 8)}</h1>
            <span className="px-2.5 py-0.5 rounded-full text-xs font-bold bg-primary/10 text-primary">
              {booking.status}
            </span>
          </div>
          <p className="text-sm text-muted-foreground mt-1">{booking.category.name} • {booking.address || 'Ahmedabad'}</p>
        </div>
        <div className="flex gap-2">
          {isCancellable && (
            <SOSButton bookingId={booking.id} />
          )}
          {isCompleted && (
            <Link href={`/customer/book?query=${encodeURIComponent(booking.category.name)}`}>
              <Button variant="outline" size="sm">Book Again</Button>
            </Link>
          )}
        </div>
      </header>

      {/* Booking status timeline */}
      <section className="bg-card p-5 rounded-xl border shadow-xs">
        <h3 className="font-bold text-sm text-foreground mb-4">Job Status History</h3>
        <BookingTimeline statusHistory={booking.statusHistory} />
      </section>

      {showPin && (
        <section className="bg-card p-5 rounded-xl border shadow-xs text-center">
          <ServicePinDisplay pin={booking.servicePin || '4827'} />
          <p className="text-xs text-muted-foreground mt-2">
            Share this 4-digit security PIN with the worker when they arrive at your location to begin work.
          </p>
        </section>
      )}

      {isTravelling && booking.worker && (
        <Card className="border-primary/50 bg-primary/5">
          <CardContent className="p-4 flex flex-col gap-3">
            <div className="flex justify-between items-center">
              <h3 className="font-semibold text-sm flex items-center gap-2 text-primary">
                <Map className="h-4 w-4" /> Live Worker Tracking
              </h3>
            </div>
            <LiveMap 
              height="200px"
              center={
                booking.worker.latitude && booking.worker.longitude
                  ? [booking.worker.latitude, booking.worker.longitude]
                  : booking.latitude && booking.longitude 
                    ? [booking.latitude, booking.longitude]
                    : undefined
              }
              markers={[
                ...(booking.latitude && booking.longitude ? [{
                  lat: booking.latitude,
                  lng: booking.longitude,
                  label: "Service Location",
                }] : []),
                ...(booking.worker.latitude && booking.worker.longitude ? [{
                  lat: booking.worker.latitude,
                  lng: booking.worker.longitude,
                  label: `${booking.worker.user.name || 'Worker'} (En Route)`,
                  isWorker: true,
                }] : [])
              ]}
            />
          </CardContent>
        </Card>
      )}

      {booking.worker && (
        <section className="space-y-3">
          <h2 className="text-base font-bold text-foreground">Assigned Worker</h2>
          <WorkerCard worker={booking.worker} href={`/customer/workers/${booking.worker.id}`} />
        </section>
      )}

      {booking.materialRequests && booking.materialRequests.length > 0 && (
        <section className="space-y-3">
          <h2 className="text-base font-bold text-foreground">Additional Material Approvals</h2>
          <div className="flex flex-col gap-3">
            {booking.materialRequests.map((mat: any) => (
              <MaterialApproval key={mat.id} material={mat} bookingId={booking.id} />
            ))}
          </div>
        </section>
      )}

      {booking.jobProofs && booking.jobProofs.length > 0 && (
        <section className="space-y-3">
          <h2 className="text-base font-bold text-foreground">Before & After Job Proof</h2>
          <ProofGallery proofs={booking.jobProofs} />
        </section>
      )}

      {isCompleted && booking.invoice && (
        <section className="space-y-3">
          <h2 className="text-base font-bold text-foreground">Digital Tax Invoice</h2>
          <InvoiceView invoice={booking.invoice} />
          {booking.payment && <PaymentSummary payment={booking.payment} />}
        </section>
      )}

      {isCompleted && booking.warranty && (
        <Card className="border-green-500/30 bg-green-500/5 p-4">
          <CardContent className="p-0 flex items-center gap-3">
            <ShieldCheck className="h-6 w-6 text-green-600 shrink-0" />
            <div>
              <p className="font-bold text-sm text-green-800">Cooperative Service Warranty Active</p>
              <p className="text-xs text-green-700">
                Valid until {new Date(booking.warranty.expiryDate).toLocaleDateString()}. Free rework covered by cooperative quality guarantee.
              </p>
            </div>
          </CardContent>
        </Card>
      )}

      {isCompleted && !booking.rating && (
        <section className="space-y-3 mt-2">
          <RatingInput bookingId={booking.id} />
        </section>
      )}

      <CustomerBookingActions
        bookingId={booking.id}
        invoice={booking.invoice}
        payment={booking.payment}
        status={booking.status}
      />
    </div>
  );
}

import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { redirect } from 'next/navigation';
import { BookingCard } from '@/components/shared/booking-card';
import { EmptyState } from '@/components/shared/empty-state';
import { Tabs, TabsContent, TabsList, TabsTrigger } from '@/components/ui/tabs';

export default async function BookingsPage() {
  const session = await auth();
  
  if (!session || !session.user) {
    redirect('/login');
  }

  const customerId = session.user.customerId;

  const allBookings = customerId
    ? await prisma.booking.findMany({
        where: { customerId },
        include: {
          category: true,
          worker: {
            include: {
              user: true,
            },
          },
        },
        orderBy: { createdAt: 'desc' },
      })
    : [];

  const active = allBookings.filter(b => ['REQUESTED', 'ACCEPTED', 'TRAVELLING', 'ARRIVED', 'IN_PROGRESS'].includes(b.status));
  const upcoming = allBookings.filter(b => ['REQUESTED', 'ACCEPTED'].includes(b.status));
  const completed = allBookings.filter(b => b.status === 'COMPLETED');

  const renderList = (list: any[]) => {
    if (list.length === 0) return <EmptyState title="No bookings found" description="You don't have any bookings in this category." />;
    return (
      <div className="flex flex-col gap-4 mt-4">
        {list.map(booking => (
          <BookingCard key={booking.id} booking={booking} href={`/customer/bookings/${booking.id}`} />
        ))}
      </div>
    );
  };

  return (
    <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-7xl mx-auto w-full">
      <header>
        <h1 className="text-2xl font-bold tracking-tight mb-2">My Bookings</h1>
        <p className="text-muted-foreground">Manage your service requests and history.</p>
      </header>

      <Tabs defaultValue="active" className="w-full">
        <TabsList className="w-full grid grid-cols-4 h-auto p-1">
          <TabsTrigger value="active" className="py-2 text-xs sm:text-sm">Active</TabsTrigger>
          <TabsTrigger value="upcoming" className="py-2 text-xs sm:text-sm">Upcoming</TabsTrigger>
          <TabsTrigger value="completed" className="py-2 text-xs sm:text-sm">Past</TabsTrigger>
          <TabsTrigger value="all" className="py-2 text-xs sm:text-sm">All</TabsTrigger>
        </TabsList>
        <TabsContent value="active">{renderList(active)}</TabsContent>
        <TabsContent value="upcoming">{renderList(upcoming)}</TabsContent>
        <TabsContent value="completed">{renderList(completed)}</TabsContent>
        <TabsContent value="all">{renderList(allBookings)}</TabsContent>
      </Tabs>
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardContent } from '@/components/ui/card';
import { Label } from '@/components/ui/label';
import { AlertTriangle, MapPin, Zap, Droplets, Wrench } from 'lucide-react';
import { toast } from 'sonner';

const emergencyCategories = [
  { id: 'electrical', name: 'Electrical Emergency', icon: Zap, color: 'text-yellow-500', bg: 'bg-yellow-500/10' },
  { id: 'water', name: 'Water Leakage', icon: Droplets, color: 'text-blue-500', bg: 'bg-blue-500/10' },
  { id: 'plumbing', name: 'Plumbing Emergency', icon: Wrench, color: 'text-orange-500', bg: 'bg-orange-500/10' },
];

export default function EmergencyBookingPage() {
  const router = useRouter();
  const [selectedCategory, setSelectedCategory] = useState<string | null>(null);
  const [address, setAddress] = useState('');
  const [loading, setLoading] = useState(false);

  const handleBookEmergency = async () => {
    if (!selectedCategory || !address) {
      toast.error('Please select a category and provide an address.');
      return;
    }

    setLoading(true);
    try {
      const res = await fetch('/api/bookings/emergency', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ category: selectedCategory, address })
      });

      if (!res.ok) throw new Error('Failed to book emergency service');
      const data = await res.json();

      router.push(`/customer/bookings/${data.id}`);
    } catch (_error) {
      toast.error('Something went wrong. Please try again.');
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col gap-6 p-4 md:p-8 max-w-xl mx-auto w-full">
      <header className="text-center flex flex-col items-center">
        <div className="w-16 h-16 bg-destructive/10 rounded-full flex items-center justify-center mb-4 text-destructive">
          <AlertTriangle className="h-8 w-8" />
        </div>
        <h1 className="text-2xl font-bold tracking-tight text-destructive mb-2">Emergency Service</h1>
        <p className="text-muted-foreground">We'll dispatch the nearest available qualified worker immediately.</p>
      </header>

      <div className="space-y-4 mt-4">
        <Label className="text-base">1. What's the emergency?</Label>
        <div className="grid grid-cols-1 sm:grid-cols-3 gap-3">
          {emergencyCategories.map(cat => {
            const Icon = cat.icon;
            const isSelected = selectedCategory === cat.id;
            return (
              <Card 
                key={cat.id}
                className={`cursor-pointer transition-all border-2 ${isSelected ? 'border-destructive bg-destructive/5' : 'border-border hover:border-destructive/50'}`}
                onClick={() => setSelectedCategory(cat.id)}
              >
                <CardContent className="flex flex-col items-center justify-center p-4 gap-2 text-center h-full">
                  <div className={`p-3 rounded-full ${cat.bg} ${cat.color}`}>
                    <Icon className="h-6 w-6" />
                  </div>
                  <span className="font-medium text-sm">{cat.name}</span>
                </CardContent>
              </Card>
            );
          })}
        </div>
      </div>

      <div className="space-y-4">
        <Label className="text-base">2. Where do you need help?</Label>
        <div className="relative">
          <MapPin className="absolute left-3 top-1/2 -translate-y-1/2 h-5 w-5 text-muted-foreground" />
          <Input 
            value={address}
            onChange={e => setAddress(e.target.value)}
            placeholder="Enter your full address" 
            className="pl-10 h-12"
          />
        </div>
      </div>

      <Button 
        size="lg" 
        variant="destructive" 
        className="w-full h-14 text-lg font-bold mt-4"
        onClick={handleBookEmergency}
        disabled={loading || !selectedCategory || !address}
      >
        {loading ? 'FINDING WORKER...' : 'REQUEST EMERGENCY HELP'}
      </Button>
    </div>
  );
}

'use client';

import { useState, useEffect, useRef } from 'react';
import { Button } from '@/components/ui/button';
import { NotificationItem } from '@/components/shared/notification-item';
import { EmptyState } from '@/components/shared/empty-state';
import { CheckCheck } from 'lucide-react';
import { Skeleton } from '@/components/ui/skeleton';

export default function NotificationsPage() {
  const [notifications, setNotifications] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);
  const channelRef = useRef<any>(null);

  useEffect(() => {
    let cancelled = false;

    async function init() {
      try {
        const [sessionRes, notifRes] = await Promise.all([
          fetch('/api/auth/session'),
          fetch('/api/notifications'),
        ]);
        const sessionData = await sessionRes.json();
        const data = await notifRes.json();

        if (cancelled) return;
        setNotifications(data.notifications || []);

        const userId = sessionData?.user?.id;
        if (userId) {
          const { supabase } = await import('@/lib/supabase');
          if (cancelled) return;

          const ch = supabase
            .channel(`customer-notifications-${userId}`)
            .on(
              'postgres_changes',
              { event: 'INSERT', schema: 'public', table: 'Notification', filter: `userId=eq.${userId}` },
              () => {
                fetch('/api/notifications')
                  .then(r => r.json())
                  .then(d => {
                    if (!cancelled) setNotifications(d.notifications || []);
                  });
              }
            )
            .subscribe();

          channelRef.current = ch;
        }
      } catch (err) {
        console.error(err);
      } finally {
        if (!cancelled) setLoading(false);
      }
    }
    init();

    return () => {
      cancelled = true;
      if (channelRef.current) {
        import('@/lib/supabase').then(({ supabase }) => {
          supabase.removeChannel(channelRef.current);
          channelRef.current = null;
        });
      }
    };
  }, []);

  const markAllAsRead = async () => {
    try {
      await fetch('/api/notifications', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ markAll: true }),
      });
      setNotifications(notifications.map(n => ({ ...n, isRead: true })));
    } catch (err) {
      console.error(err);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-2xl mx-auto w-full">
        <header className="flex items-center justify-between">
          <div>
            <Skeleton className="h-8 w-48 mb-2" />
            <Skeleton className="h-4 w-64" />
          </div>
        </header>
        <div className="flex flex-col gap-2 mt-2">
          {[1, 2, 3, 4].map(i => (
            <div key={i} className="flex gap-4 p-4 border-b">
              <Skeleton className="h-10 w-10 rounded-full shrink-0" />
              <div className="flex-1 space-y-2">
                <div className="flex justify-between">
                  <Skeleton className="h-4 w-1/3" />
                  <Skeleton className="h-3 w-16" />
                </div>
                <Skeleton className="h-3 w-full" />
                <Skeleton className="h-3 w-4/5" />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-2xl mx-auto w-full">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight mb-1">Notifications</h1>
          <p className="text-muted-foreground text-sm">Stay updated on your bookings.</p>
        </div>
        {notifications.length > 0 && (
          <Button variant="ghost" size="sm" onClick={markAllAsRead} className="gap-2">
            <CheckCheck className="h-4 w-4" />
            Mark all read
          </Button>
        )}
      </header>

      {notifications.length === 0 ? (
        <EmptyState title="No notifications" description="You're all caught up!" />
      ) : (
        <div className="flex flex-col gap-2">
          {notifications.map(notification => (
            <NotificationItem key={notification.id} notification={notification} />
          ))}
        </div>
      )}
    </div>
  );
}

