import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { redirect } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { MapPin, AlertTriangle } from "lucide-react";
import { findWorkersForOrganizationRequest, assignWorkerToOrganizationRequest } from "@/services/organization";
import { revalidatePath } from "next/cache";

export default async function InstitutionRequestDetailsPage({ 
  params 
}: { 
  params: { id: string } 
}) {
  const session = await auth();
  if (!session?.user) redirect("/login");

  const institutionId = session.user.institutionId;
  if (!institutionId) redirect("/login");

  const requestId = params.id;

  const request = await prisma.institutionServiceRequest.findUnique({
    where: { id: requestId, institutionId },
    include: {
      location: true,
      category: true,
      bookings: {
        include: { worker: { include: { user: true, cooperative: true } } }
      }
    }
  });

  if (!request) {
    return <div className="p-8 text-center text-red-500">Request not found or access denied.</div>;
  }

  // Find workers if still open
  let matches: any[] = [];
  let error = "";
  if (request.status === "OPEN") {
    try {
      matches = await findWorkersForOrganizationRequest(requestId, "INSTITUTION", request.priority as 'NORMAL' | 'URGENT' | 'EMERGENCY');
    } catch (e: any) {
      error = e.message;
    }
  }

  async function handleAssign(formData: FormData) {
    "use server";
    const workerId = formData.get("workerId") as string;
    if (!workerId) return;

    try {
      const session = await auth();
      if (!session?.user) throw new Error("Unauthorized");

      await assignWorkerToOrganizationRequest({
        requestId,
        type: "INSTITUTION",
        workerId,
        assignedByUserId: session.user.id as string,
      });
      revalidatePath(`/institution/services/${requestId}`);
    } catch (e: any) {
      console.error(e);
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Request #{request.id.slice(-6)}</h2>
          <p className="text-muted-foreground">{request.title}</p>
        </div>
        <Badge variant={request.status === "OPEN" ? "destructive" : "default"} className="text-sm px-3 py-1">
          {request.status}
        </Badge>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Request Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid md:grid-cols-2 gap-4">
            <div>
              <p className="text-sm font-medium text-muted-foreground">Category</p>
              <p>{request.category?.name || "N/A"}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-muted-foreground">Location</p>
              <p className="flex items-center gap-1 text-sm">
                <MapPin className="w-4 h-4 text-muted-foreground" />
                {request.location?.name || "Not specified"}
              </p>
            </div>
            <div className="col-span-full">
              <p className="text-sm font-medium text-muted-foreground">Description</p>
              <p className="text-sm">{request.description}</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {request.status === "OPEN" && (
        <div className="space-y-4">
          <h3 className="text-xl font-semibold flex items-center gap-2">
            Nearby Workers
            <Badge variant="secondary" className="text-xs">FairMatch Recommended</Badge>
          </h3>
          {error && <div className="p-4 bg-red-500/10 text-red-500 rounded-lg">{error}</div>}

          <div className="grid gap-4 md:grid-cols-2">
            {matches.map((match, i) => (
              <Card key={match.worker.id} className={i === 0 ? "border-teal-500 shadow-md" : ""}>
                <CardContent className="p-4 flex flex-col h-full">
                  <div className="flex justify-between items-start mb-2">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-secondary rounded-full overflow-hidden flex items-center justify-center">
                        {match.worker.user.avatar ? (
                          <img src={match.worker.user.avatar} alt={match.worker.user.name} className="w-full h-full object-cover" />
                        ) : (
                          <span className="font-medium">{match.worker.user.name.charAt(0)}</span>
                        )}
                      </div>
                      <div>
                        <div className="font-semibold">{match.worker.user.name}</div>
                        <p className="text-xs text-muted-foreground">{match.worker.primaryTrade}</p>
                      </div>
                    </div>
                    <Badge variant="outline" className="bg-teal-500/10 text-teal-600 border-teal-200">
                      Score: {match.match_score}
                    </Badge>
                  </div>

                  <div className="space-y-2 text-sm mb-4 flex-1">
                    <p className="text-xs text-muted-foreground italic">
                      {match.worker.cooperative?.name ? `From ${match.worker.cooperative.name}` : "Independent Worker"}
                    </p>
                    <p className="text-xs bg-muted p-2 rounded-md">{match.explanation}</p>
                  </div>

                  <form action={handleAssign} className="w-full mt-auto">
                    <input type="hidden" name="workerId" value={match.worker.id} />
                    <Button type="submit" className="w-full bg-teal-600 hover:bg-teal-700" variant={i === 0 ? "default" : "secondary"}>
                      Assign Worker
                    </Button>
                  </form>
                </CardContent>
              </Card>
            ))}
            {matches.length === 0 && !error && (
              <div className="col-span-full p-8 text-center border rounded-lg border-dashed">
                <AlertTriangle className="w-8 h-8 mx-auto text-amber-500 mb-2" />
                <p className="font-medium">No eligible workers found nearby</p>
                <p className="text-sm text-muted-foreground">This request might be too far from our worker network, or no workers are available.</p>
              </div>
            )}
          </div>
        </div>
      )}

      {request.status !== "OPEN" && request.bookings?.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Assigned Job</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex items-center justify-between p-4 bg-muted/50 rounded-lg">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-secondary rounded-full flex items-center justify-center">
                  {request.bookings[0].worker.user.avatar ? (
                    <img src={request.bookings[0].worker.user.avatar} className="w-full h-full object-cover rounded-full" />
                  ) : (
                    request.bookings[0].worker.user.name.charAt(0)
                  )}
                </div>
                <div>
                  <p className="font-semibold">{request.bookings[0].worker.user.name}</p>
                  <p className="text-sm text-muted-foreground">{request.bookings[0].worker.cooperative?.name}</p>
                </div>
              </div>
              <div className="text-right">
                <Badge>{request.bookings[0].status}</Badge>
                <p className="text-xs text-muted-foreground mt-1">Booking #{request.bookings[0].id.slice(0,6)}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

'use client';

import { useState, Suspense } from 'react';
import { useRouter, useSearchParams } from 'next/navigation';
import Link from 'next/link';
import { Loader2, CheckCircle2, Lock, ArrowLeft, Shield, EyeOff, Eye } from 'lucide-react';

function ResetPasswordForm() {
  const _router = useRouter();
  const searchParams = useSearchParams();
  const token = searchParams.get('token');

  const [password, setPassword] = useState('');
  const [confirmPassword, setConfirmPassword] = useState('');
  const [showPassword, setShowPassword] = useState(false);
  const [showConfirmPassword, setShowConfirmPassword] = useState(false);

  const [isLoading, setIsLoading] = useState(false);
  const [isSuccess, setIsSuccess] = useState(false);
  const [error, setError] = useState('');

  if (!token) {
    return (
      <div className="text-center bg-secondary/50 p-8 rounded-2xl border border-border/80 shadow-sm mt-8">
        <h3 className="text-lg font-bold text-foreground mb-2">Invalid Link</h3>
        <p className="text-sm text-muted-foreground mb-6">
          This password reset link is missing or invalid. It may have expired.
        </p>
        <Link
          href="/forgot-password"
          className="w-full flex justify-center py-3 bg-primary text-white text-sm font-bold rounded-xl hover:bg-primary/90 transition-all shadow-md shadow-primary/20"
        >
          Request New Link
        </Link>
      </div>
    );
  }

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    if (isLoading) return;
    setError('');

    if (password.length < 8) {
      setError('Password must be at least 8 characters long.');
      return;
    }

    if (password !== confirmPassword) {
      setError('Passwords do not match.');
      return;
    }

    setIsLoading(true);

    try {
      const res = await fetch('/api/auth/reset-password', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ token, password }),
      });

      const data = await res.json();

      if (!res.ok) {
        throw new Error(data.error || 'Failed to reset password');
      }

      setIsSuccess(true);
    } catch (err: any) {
      setError(err.message || 'An unexpected error occurred. Please try again.');
    } finally {
      setIsLoading(false);
    }
  };

  if (isSuccess) {
    return (
      <div className="mt-8 text-center bg-secondary/50 p-8 rounded-2xl border border-border/80 shadow-sm">
        <CheckCircle2 className="mx-auto h-12 w-12 text-emerald-500 mb-4" />
        <h3 className="text-lg font-bold text-foreground mb-2">Password reset successfully</h3>
        <p className="text-sm text-muted-foreground mb-6">
          Your account is secure. You can now log in with your new password.
        </p>
        <Link
          href="/login"
          className="w-full flex justify-center py-3 bg-primary text-white text-sm font-bold rounded-xl hover:bg-primary/90 transition-all shadow-md shadow-primary/20"
        >
          Go to Login
        </Link>
      </div>
    );
  }

  return (
    <>
      <p className="text-muted-foreground mb-8 text-sm">Please enter your new password below.</p>

      {error && (
        <div className="mb-6 p-3 bg-destructive/10 border border-destructive/30 rounded-xl text-xs text-destructive font-medium">
          {error}
        </div>
      )}

      <form className="space-y-5" onSubmit={handleSubmit}>
        <div>
          <label htmlFor="password" className="block text-xs font-semibold text-foreground mb-1.5">
            New Password
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none">
              <Lock className="h-4 w-4 text-muted-foreground" />
            </div>
            <input
              id="password"
              name="password"
              type={showPassword ? "text" : "password"}
              required
              minLength={8}
              value={password}
              onChange={(e) => setPassword(e.target.value)}
              className="block w-full pl-10 pr-10 py-2.5 border border-border/80 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition-colors bg-secondary/50 text-foreground placeholder:text-muted-foreground"
              placeholder="Min. 8 characters"
              disabled={isLoading}
            />
            <button
              type="button"
              onClick={() => setShowPassword(!showPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
            >
              {showPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
            </button>
          </div>
        </div>

        <div>
          <label htmlFor="confirmPassword" className="block text-xs font-semibold text-foreground mb-1.5">
            Confirm New Password
          </label>
          <div className="relative">
            <div className="absolute inset-y-0 left-0 pl-3.5 flex items-center pointer-events-none">
              <Lock className="h-4 w-4 text-muted-foreground" />
            </div>
            <input
              id="confirmPassword"
              name="confirmPassword"
              type={showConfirmPassword ? "text" : "password"}
              required
              minLength={8}
              value={confirmPassword}
              onChange={(e) => setConfirmPassword(e.target.value)}
              className="block w-full pl-10 pr-10 py-2.5 border border-border/80 rounded-xl text-sm focus:outline-none focus:ring-2 focus:ring-primary/30 focus:border-primary transition-colors bg-secondary/50 text-foreground placeholder:text-muted-foreground"
              placeholder="Confirm new password"
              disabled={isLoading}
            />
            <button
              type="button"
              onClick={() => setShowConfirmPassword(!showConfirmPassword)}
              className="absolute right-3 top-1/2 -translate-y-1/2 text-muted-foreground hover:text-foreground transition-colors"
            >
              {showConfirmPassword ? <EyeOff className="w-4 h-4" /> : <Eye className="w-4 h-4" />}
            </button>
          </div>
        </div>

        <button
          type="submit"
          disabled={isLoading}
          className="w-full py-3 bg-primary text-white text-sm font-bold rounded-xl hover:bg-primary/90 transition-all shadow-md shadow-primary/20 disabled:opacity-50 flex items-center justify-center gap-2 cursor-pointer"
        >
          {isLoading ? (
            <>
              <Loader2 className="w-4 h-4 animate-spin" />
              Resetting Password...
            </>
          ) : (
            'Reset Password'
          )}
        </button>

        <div className="mt-6 text-center">
          <Link href="/login" className="inline-flex items-center text-xs text-muted-foreground hover:text-foreground transition-colors font-medium">
            <ArrowLeft className="w-4 h-4 mr-1.5" />
            Back to login
          </Link>
        </div>
      </form>
    </>
  );
}

