    phone: '',
    password: '',
    confirmPassword: '',
    address: '',
    units: '',
  });
  const [error, setError] = useState('');

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setError('');

    if (!formData.name.trim() || !formData.contactPerson.trim() || !formData.email.trim() || !formData.password || !formData.phone.trim()) {
      setError('Please fill in all required fields.');
      return;
    }

    const cleanedPhone = formData.phone.replace(/\D/g, '');
    const isPhoneValid = (cleanedPhone.length === 10 && /^[6-9]\d{9}$/.test(cleanedPhone)) || 
                         (cleanedPhone.length === 12 && cleanedPhone.startsWith('91') && /^[6-9]\d{9}$/.test(cleanedPhone.substring(2)));

    if (!isPhoneValid) {
      setError('Please enter a valid 10-digit Indian mobile number.');
      return;
    }

    if (formData.password.length < 6) {
      setError('Password must be at least 6 characters.');
      return;
    }

    if (formData.password !== formData.confirmPassword) {
      setError('Passwords do not match.');
      return;
    }

    setLoading(true);
    try {
      const res = await fetch('/api/auth/register-society', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          name: formData.name.trim(),
          contactPerson: formData.contactPerson.trim(),
          email: formData.email.trim().toLowerCase(),
          phone: formData.phone.trim(),
          password: formData.password,
          address: formData.address.trim(),
          units: formData.units,
        }),
      });

      const data = await res.json();
      if (!res.ok) {
        throw new Error(data.error || 'Registration failed');
      }

      toast.success('Housing Society registered successfully! Please sign in.');
      router.push('/login?registered=true');
    } catch (err: any) {
      setError(err.message || 'Registration failed. Please try again.');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="min-h-screen bg-background text-foreground flex items-center justify-center p-4 md:p-6">
      <div className="w-full max-w-md">
        <div className="flex items-center justify-center gap-2.5 mb-6">
          <div className="w-10 h-10 bg-primary rounded-xl flex items-center justify-center shadow-md shadow-primary/20">
            <Shield className="w-6 h-6 text-white" />
          </div>
          <span className="font-bold text-xl text-foreground">Co-opConnect</span>
        </div>

        <Card className="border border-border/80 shadow-lg bg-card">
          <CardHeader className="text-center pb-4">
            <CardTitle className="text-xl font-bold text-foreground tracking-tight">Register Housing Society</CardTitle>
            <p className="text-xs text-muted-foreground mt-1">
              Create an account for your society's maintenance and service needs
            </p>
          </CardHeader>
          <CardContent>
            {error && (
              <div className="mb-4 p-3 bg-destructive/10 border border-destructive/30 rounded-xl text-xs text-destructive font-medium">
                {error}
              </div>
            )}

            <form onSubmit={handleSubmit} className="space-y-3.5 text-xs">
              <div>
                <label className="font-semibold text-foreground block mb-1">Society Name *</label>
                <Input
                  required
                  type="text"
                  value={formData.name}
                  onChange={(e) => setFormData({ ...formData, name: e.target.value })}
                  placeholder="e.g. Sunrise Residency"
                  className="h-10 text-xs bg-secondary/50 border-border text-foreground"
                />
              </div>

              <div>
                <label className="font-semibold text-foreground block mb-1">Contact Person Name *</label>
                <Input
                  required
                  type="text"
                  value={formData.contactPerson}
                  onChange={(e) => setFormData({ ...formData, contactPerson: e.target.value })}
                  placeholder="e.g. Amit Patel"
                  className="h-10 text-xs bg-secondary/50 border-border text-foreground"
                />
              </div>

              <div>
                <label className="font-semibold text-foreground block mb-1">Admin Email Address *</label>
                <Input
                  required
                  type="email"
                  value={formData.email}
                  onChange={(e) => setFormData({ ...formData, email: e.target.value })}
                  placeholder="name@example.com"
                  className="h-10 text-xs bg-secondary/50 border-border text-foreground"
                />
              </div>

              <div>
                <label className="font-semibold text-foreground block mb-1">Contact Phone Number *</label>
                <Input
                  required
                  type="tel"
                  value={formData.phone}
                  onChange={(e) => setFormData({ ...formData, phone: e.target.value })}
                  placeholder="+91 98765 43210"
                  className="h-10 text-xs bg-secondary/50 border-border text-foreground"
                />
              </div>

              <div className="grid grid-cols-1 sm:grid-cols-2 gap-2">
                <div>
                  <label className="font-semibold text-foreground block mb-1">Password *</label>
                  <Input
                    required
                    type="password"
                    value={formData.password}
                    onChange={(e) => setFormData({ ...formData, password: e.target.value })}
                    placeholder="Min 6 characters"
                    className="h-10 text-xs bg-secondary/50 border-border text-foreground"
                  />
                </div>
                <div>
                  <label className="font-semibold text-foreground block mb-1">Confirm Password *</label>
                  <Input
                    required
                    type="password"
                    value={formData.confirmPassword}
                    onChange={(e) => setFormData({ ...formData, confirmPassword: e.target.value })}
                    placeholder="Re-enter password"
                    className="h-10 text-xs bg-secondary/50 border-border text-foreground"
                  />
                </div>
              </div>

              <div className="grid grid-cols-[2fr_1fr] gap-2">
                <div>
                  <label className="font-semibold text-foreground block mb-1">Address</label>
                  <Input
                    value={formData.address}
                    onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                    placeholder="Society Address"
                    className="h-10 text-xs bg-secondary/50 border-border text-foreground"
                  />
                </div>
                <div>
                  <label className="font-semibold text-foreground block mb-1">Total Units</label>
                  <Input
                    type="number"
                    min="1"
                    value={formData.units}
                    onChange={(e) => setFormData({ ...formData, units: e.target.value })}
                    placeholder="e.g. 100"
                    className="h-10 text-xs bg-secondary/50 border-border text-foreground"
                  />
                </div>
              </div>

              <Button
                type="submit"
                className="w-full h-11 text-xs font-bold mt-3 bg-amber-500 hover:bg-amber-600 text-white shadow-md shadow-amber-500/20 cursor-pointer"
                disabled={loading}
              >
                {loading ? (
                  <span className="flex items-center gap-2">
                    <Loader2 className="h-4 w-4 animate-spin" /> Registering Society...
                  </span>
                ) : (
                  <span className="flex items-center gap-2">
                    <Building2 className="h-4 w-4" /> Register Housing Society
                  </span>
                )}
              </Button>
            </form>

            <div className="mt-5 pt-4 border-t border-border/80 text-center space-y-2 text-xs">
              <p className="text-muted-foreground">
                Already registered?{' '}
                <Link href="/login" className="text-primary font-bold hover:underline">
                  Sign In
                </Link>
              </p>
              <p className="text-muted-foreground">
                Looking for other options?{' '}
                <Link href="/register" className="text-primary font-semibold hover:underline">
                  View all registration options
                </Link>
              </p>
            </div>
          </CardContent>
        </Card>
      </div>
    </div>
  );
}

import { auth } from "@/lib/auth";
import { prisma } from "@/lib/prisma";
import { redirect } from "next/navigation";
import { Card, CardContent, CardHeader, CardTitle } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { Button } from "@/components/ui/button";
import { MapPin, AlertTriangle } from "lucide-react";
import { findWorkersForOrganizationRequest, assignWorkerToOrganizationRequest } from "@/services/organization";
import { revalidatePath } from "next/cache";

export default async function SocietyRequestDetailsPage({ 
  params 
}: { 
  params: { id: string } 
}) {
  const session = await auth();
  if (!session?.user) redirect("/login");

  const societyId = session.user.societyId;
  if (!societyId) redirect("/login");

  const requestId = params.id;

  const request = await prisma.societyServiceRequest.findUnique({
    where: { id: requestId, societyId },
    include: {
      location: true,
      category: true,
      bookings: {
        include: { worker: { include: { user: true, cooperative: true } } }
      }
    }
  });

  if (!request) {
    return <div className="p-8 text-center text-red-500">Request not found or access denied.</div>;
  }

  // Find workers if still open
  let matches: any[] = [];
  let error = "";
  if (request.status === "OPEN") {
    try {
      matches = await findWorkersForOrganizationRequest(requestId, "SOCIETY", request.priority as 'NORMAL' | 'URGENT' | 'EMERGENCY');
    } catch (e: any) {
      error = e.message;
    }
  }

  async function handleAssign(formData: FormData) {
    "use server";
    const workerId = formData.get("workerId") as string;
    if (!workerId) return;

    try {
      const session = await auth();
      if (!session?.user) throw new Error("Unauthorized");

      await assignWorkerToOrganizationRequest({
        requestId,
        type: "SOCIETY",
        workerId,
        assignedByUserId: session.user.id as string,
      });
      revalidatePath(`/society/requests/${requestId}`);
    } catch (e: any) {
      console.error(e);
    }
  }

  return (
    <div className="space-y-6">
      <div className="flex justify-between items-center">
        <div>
          <h2 className="text-2xl font-bold tracking-tight">Request #{request.id.slice(-6)}</h2>
          <p className="text-muted-foreground">{request.title}</p>
        </div>
        <Badge variant={request.status === "OPEN" ? "destructive" : "default"} className="text-sm px-3 py-1">
          {request.status}
        </Badge>
      </div>

      <Card>
        <CardHeader>
          <CardTitle>Request Details</CardTitle>
        </CardHeader>
        <CardContent className="space-y-4">
          <div className="grid md:grid-cols-2 gap-4">
            <div>
              <p className="text-sm font-medium text-muted-foreground">Category</p>
              <p>{request.category?.name || "N/A"}</p>
            </div>
            <div>
              <p className="text-sm font-medium text-muted-foreground">Location</p>
              <p className="flex items-center gap-1 text-sm">
                <MapPin className="w-4 h-4 text-muted-foreground" />
                {request.location?.name || request.area}
              </p>
            </div>
            <div className="col-span-full">
              <p className="text-sm font-medium text-muted-foreground">Description</p>
              <p className="text-sm">{request.description}</p>
            </div>
          </div>
        </CardContent>
      </Card>

      {request.status === "OPEN" && (
        <div className="space-y-4">
          <h3 className="text-xl font-semibold flex items-center gap-2">
            Nearby Workers
            <Badge variant="secondary" className="text-xs">FairMatch Recommended</Badge>
          </h3>
          {error && <div className="p-4 bg-red-500/10 text-red-500 rounded-lg">{error}</div>}

          <div className="grid gap-4 md:grid-cols-2">
            {matches.map((match, i) => (
              <Card key={match.worker.id} className={i === 0 ? "border-amber-500 shadow-md" : ""}>
                <CardContent className="p-4 flex flex-col h-full">
                  <div className="flex justify-between items-start mb-2">
                    <div className="flex items-center gap-3">
                      <div className="w-10 h-10 bg-secondary rounded-full overflow-hidden flex items-center justify-center">
                        {match.worker.user.avatar ? (
                          <img src={match.worker.user.avatar} alt={match.worker.user.name} className="w-full h-full object-cover" />
                        ) : (
                          <span className="font-medium">{match.worker.user.name.charAt(0)}</span>
                        )}
                      </div>
                      <div>
                        <div className="font-semibold">{match.worker.user.name}</div>
                        <p className="text-xs text-muted-foreground">{match.worker.primaryTrade}</p>
                      </div>
                    </div>
                    <Badge variant="outline" className="bg-amber-500/10 text-amber-600 border-amber-200">
                      Score: {match.match_score}
                    </Badge>
                  </div>

                  <div className="space-y-2 text-sm mb-4 flex-1">
                    <p className="text-xs text-muted-foreground italic">
                      {match.worker.cooperative?.name ? `From ${match.worker.cooperative.name}` : "Independent Worker"}
                    </p>
                    <p className="text-xs bg-muted p-2 rounded-md">{match.explanation}</p>
                  </div>

                  <form action={handleAssign} className="w-full mt-auto">
                    <input type="hidden" name="workerId" value={match.worker.id} />
                    <Button type="submit" className="w-full" variant={i === 0 ? "default" : "secondary"}>
                      Assign Worker
                    </Button>
                  </form>
                </CardContent>
              </Card>
            ))}
            {matches.length === 0 && !error && (
              <div className="col-span-full p-8 text-center border rounded-lg border-dashed">
                <AlertTriangle className="w-8 h-8 mx-auto text-amber-500 mb-2" />
                <p className="font-medium">No eligible workers found nearby</p>
                <p className="text-sm text-muted-foreground">This request might be too far from our worker network, or no workers are available.</p>
              </div>
            )}
          </div>
        </div>
      )}

      {request.status !== "OPEN" && request.bookings?.length > 0 && (
        <Card>
          <CardHeader>
            <CardTitle>Assigned Job</CardTitle>
          </CardHeader>
          <CardContent>
            <div className="flex items-center justify-between p-4 bg-muted/50 rounded-lg">
              <div className="flex items-center gap-4">
                <div className="w-12 h-12 bg-secondary rounded-full flex items-center justify-center">
                  {request.bookings[0].worker.user.avatar ? (
                    <img src={request.bookings[0].worker.user.avatar} className="w-full h-full object-cover rounded-full" />
                  ) : (
                    request.bookings[0].worker.user.name.charAt(0)
                  )}
                </div>
                <div>
                  <p className="font-semibold">{request.bookings[0].worker.user.name}</p>
                  <p className="text-sm text-muted-foreground">{request.bookings[0].worker.cooperative?.name}</p>
                </div>
              </div>
              <div className="text-right">
                <Badge>{request.bookings[0].status}</Badge>
                <p className="text-xs text-muted-foreground mt-1">Booking #{request.bookings[0].id.slice(0,6)}</p>
              </div>
            </div>
          </CardContent>
        </Card>
      )}
    </div>
  );
}

import { notFound } from 'next/navigation';
import { prisma } from '@/lib/prisma';
import { ShieldCheck, ShieldAlert, UserCheck, Star, AlertTriangle } from 'lucide-react';
import { Card, CardContent, CardHeader, CardTitle } from '@/components/ui/card';

export default async function WorkerVerificationPage({ params }: { params: Promise<{ publicId: string }> | { publicId: string } }) {
  const resolvedParams = await params;
  const worker = await prisma.worker.findUnique({
    where: { publicId: resolvedParams.publicId },
    include: {
      user: { select: { name: true, avatar: true } },
      cooperative: { select: { name: true } },
    }
  });

  if (!worker) {
    // Fallback to internal ID for development purposes if publicId isn't set yet
    const fallbackWorker = await prisma.worker.findUnique({
      where: { id: resolvedParams.publicId },
      include: {
        user: { select: { name: true, avatar: true } },
        cooperative: { select: { name: true } },
      }
    });
    if (!fallbackWorker) {
      notFound();
    }
    Object.assign(worker || {}, fallbackWorker);
  }

  // @ts-ignore (we know worker is assigned now)
  const w = worker!;

  const isVerified = w.verificationStatus === 'VERIFIED';
  const isDigiLocker = w.verificationMethod === 'DIGILOCKER';

  return (
    <div className="min-h-screen bg-gray-50 p-4 md:p-8 flex items-center justify-center">
      <Card className="max-w-md w-full shadow-lg border-t-4 border-t-primary">
        <CardHeader className="text-center pb-2">
          <CardTitle className="text-2xl font-bold flex flex-col items-center gap-2">
            {isVerified ? (
              <ShieldCheck className="w-16 h-16 text-green-600" />
            ) : w.verificationStatus === 'SUSPENDED' ? (
              <ShieldAlert className="w-16 h-16 text-red-600" />
            ) : (
              <AlertTriangle className="w-16 h-16 text-amber-500" />
            )}
            Co-opConnect Verification
          </CardTitle>
        </CardHeader>
        <CardContent className="space-y-6">
          <div className="text-center space-y-1">
            <h2 className="text-xl font-bold">{w.user?.name || 'Worker'}</h2>
            <p className="text-muted-foreground font-medium">{w.primaryTrade || 'Professional Service Provider'}</p>
            {w.cooperative && <p className="text-xs text-muted-foreground">{w.cooperative.name}</p>}
          </div>

          <div className="bg-gray-100 rounded-lg p-4 space-y-3">
            <div className="flex justify-between items-center text-sm border-b pb-2">
              <span className="text-muted-foreground">Status</span>
              <span className={`font-bold ${isVerified ? 'text-green-700' : 'text-red-600'}`}>
                {w.verificationStatus}
              </span>
            </div>
            <div className="flex justify-between items-center text-sm border-b pb-2">
              <span className="text-muted-foreground">Verification Method</span>
              <span className="font-medium flex items-center gap-1">
                {isDigiLocker ? <UserCheck className="w-4 h-4 text-blue-600" /> : null}
                {w.verificationMethod === 'DIGILOCKER' ? 'Identity Verified (MOCK)' : 
                 w.verificationMethod === 'ADMIN' ? 'Admin Verified' : 'Unverified'}
              </span>
            </div>
            {w.verifiedAt && (
              <div className="flex justify-between items-center text-sm border-b pb-2">
                <span className="text-muted-foreground">Verified On</span>
                <span className="font-medium">{new Date(w.verifiedAt).toLocaleDateString()}</span>
              </div>
            )}
          </div>

          <div className="grid grid-cols-2 gap-4">
            <div className="bg-white border rounded-lg p-3 text-center shadow-sm">
              <p className="text-xs text-muted-foreground">Jobs Completed</p>
              <p className="text-lg font-bold">{w.totalJobs}</p>
            </div>
            <div className="bg-white border rounded-lg p-3 text-center shadow-sm">
              <p className="text-xs text-muted-foreground">Rating</p>
              <p className="text-lg font-bold flex items-center justify-center gap-1">
                {w.averageRating.toFixed(1)} <Star className="w-3 h-3 fill-yellow-400 text-yellow-400" />
              </p>
            </div>
            <div className="bg-white border rounded-lg p-3 text-center shadow-sm">
              <p className="text-xs text-muted-foreground">Completion Rate</p>
              <p className="text-lg font-bold">{w.completionRate}%</p>
            </div>
            <div className="bg-white border rounded-lg p-3 text-center shadow-sm">
              <p className="text-xs text-muted-foreground">Punctuality</p>
              <p className="text-lg font-bold">{w.punctualityScore}%</p>
            </div>
          </div>

          {w.verificationStatus !== 'VERIFIED' && (
            <div className="bg-red-50 text-red-800 p-3 rounded-lg text-xs flex gap-2 items-start mt-4">
              <AlertTriangle className="w-4 h-4 shrink-0 mt-0.5" />
              <p>This worker is currently not permitted to accept jobs on the platform.</p>
            </div>
          )}
        </CardContent>
      </Card>
    </div>
  );
}

