        <h2 className="text-lg font-bold text-foreground flex items-center gap-2">
          <Sparkles className="h-5 w-5 text-primary" /> Discover Available Helpers Nearby
        </h2>

        <div className="grid grid-cols-1 sm:grid-cols-2 md:grid-cols-3 gap-4">
          {nearbyHelpers.map((match) => {
            const h = match.helper || match;
            const u = h.user || {};
            return (
              <Card key={h.id} className="hover:border-primary/40 transition-all">
                <CardContent className="p-4 space-y-2 text-xs">
                  <div className="flex items-center gap-3">
                    <div className="w-10 h-10 rounded-full bg-primary/10 text-primary font-bold flex items-center justify-center text-sm">
                      {u.name?.[0] || 'H'}
                    </div>
                    <div>
                      <p className="font-bold text-sm text-foreground">{u.name || 'Helper'}</p>
                      <p className="text-muted-foreground">{h.primaryTrade || 'Apprentice'} • {h.experience || 1} yr exp</p>
                    </div>
                  </div>
                  <div className="pt-2 border-t flex justify-between text-muted-foreground">
                    <span>{h.averageRating > 0 ? `⭐ ${h.averageRating.toFixed(1)}` : '⭐ New'}</span>
                    <span>📍 {match.distanceKm !== undefined ? `${match.distanceKm} km` : 'Nearby'}</span>
                    <span className="text-primary font-semibold">{match.matchScore || match.match_score || 90}% Match</span>
                  </div>
                </CardContent>
              </Card>
            );
          })}
        </div>
      </section>
    </div>
  );
}

import { auth } from '@/lib/auth';
import { prisma } from '@/lib/prisma';
import { redirect } from 'next/navigation';
import { Tabs, TabsContent, TabsList, TabsTrigger } from "@/components/ui/tabs";
import { Card, CardContent } from "@/components/ui/card";
import { Badge } from '@/components/ui/badge';
import { Button } from '@/components/ui/button';
import Link from 'next/link';
import { MapPin, Calendar } from 'lucide-react';
import { formatCurrency, formatDate } from '@/lib/utils';

export default async function WorkerJobsPage() {
  const session = await auth();
  if (!session?.user) redirect('/login');

  const workerId = session.user.workerId;

  const [activeBookings, completedBookings] = workerId
    ? await Promise.all([
        prisma.booking.findMany({
          where: {
            workerId,
            status: { in: ['REQUESTED', 'ACCEPTED', 'TRAVELLING', 'ARRIVED', 'IN_PROGRESS'] },
          },
          select: {
            id: true,
            description: true,
            address: true,
            status: true,
            createdAt: true,
            estimatedPrice: true,
            category: { select: { name: true, basePrice: true } },
            customer: { select: { user: { select: { name: true } } } },
          },
          orderBy: { createdAt: 'desc' },
        }),
        prisma.booking.findMany({
          where: {
            workerId,
            status: { in: ['COMPLETED', 'CANCELLED'] },
          },
          select: {
            id: true,
            description: true,
            address: true,
            status: true,
            createdAt: true,
            estimatedPrice: true,
            category: { select: { name: true, basePrice: true } },
            customer: { select: { user: { select: { name: true } } } },
          },
          orderBy: { createdAt: 'desc' },
          take: 50,
        }),
      ])
    : [[], []];

  const requested = activeBookings.filter((b) => b.status === 'REQUESTED');
  const accepted = activeBookings.filter((b) => b.status === 'ACCEPTED');
  const active = activeBookings.filter((b) => ['TRAVELLING', 'ARRIVED', 'IN_PROGRESS'].includes(b.status));
  const completed = completedBookings;

  const renderJobCard = (b: any) => (
    <Card key={b.id} className="bg-white border shadow-xs">
      <CardContent className="p-5 flex flex-col sm:flex-row justify-between items-start sm:items-center gap-4">
        <div className="space-y-1">
          <div className="flex items-center gap-2">
            <Badge className="bg-blue-100 text-blue-800">{b.category.name}</Badge>
            <Badge variant="outline" className="text-xs font-semibold">{b.status}</Badge>
          </div>
          <h3 className="font-bold text-gray-900">{b.description || 'Household Service Request'}</h3>
          <p className="text-xs text-gray-500 flex items-center gap-1">
            <MapPin className="w-3.5 h-3.5 text-gray-400" />
            {b.address || 'Address not provided'} • Customer: {b.customer?.user?.name || 'Customer'}
          </p>
          <div className="flex items-center gap-3 pt-1 text-xs text-gray-600">
            <span className="flex items-center gap-1"><Calendar className="w-3.5 h-3.5" />{formatDate(b.createdAt)}</span>
            <span className="flex items-center gap-1 font-semibold text-green-700">
              Est. {formatCurrency(b.estimatedPrice || b.category.basePrice || 350)}
            </span>
          </div>
        </div>
        <div className="w-full sm:w-auto">
          <Link href={`/worker/jobs/${b.id}`} className="w-full sm:w-auto">
            <Button className="bg-green-600 hover:bg-green-700 text-white w-full">
              Open Job
            </Button>
          </Link>
        </div>
      </CardContent>
    </Card>
  );

  return (
    <div className="p-4 md:p-6 max-w-5xl mx-auto space-y-6 pb-24 lg:pb-8">
      <div>
        <h1 className="text-2xl font-bold text-gray-900">Job Console</h1>
        <p className="text-sm text-gray-500">Manage incoming service requests and active tasks</p>
      </div>

      <Tabs defaultValue="active" className="space-y-4">
        <TabsList className="w-full justify-between bg-gray-100 p-1 rounded-xl">
          <TabsTrigger value="active" className="flex-1">Active ({active.length})</TabsTrigger>
          <TabsTrigger value="new" className="flex-1">New ({requested.length})</TabsTrigger>
          <TabsTrigger value="accepted" className="flex-1">Accepted ({accepted.length})</TabsTrigger>
          <TabsTrigger value="completed" className="flex-1">Completed ({completed.length})</TabsTrigger>
        </TabsList>

        <TabsContent value="active" className="space-y-3">
          {active.length === 0 ? (
            <Card className="p-8 text-center text-gray-500">No jobs currently in progress.</Card>
          ) : (
            active.map(renderJobCard)
          )}
        </TabsContent>

        <TabsContent value="new" className="space-y-3">
          {requested.length === 0 ? (
            <Card className="p-8 text-center text-gray-500">No new incoming requests.</Card>
          ) : (
            requested.map(renderJobCard)
          )}
        </TabsContent>

        <TabsContent value="accepted" className="space-y-3">
          {accepted.length === 0 ? (
            <Card className="p-8 text-center text-gray-500">No accepted jobs awaiting dispatch.</Card>
          ) : (
            accepted.map(renderJobCard)
          )}
        </TabsContent>

        <TabsContent value="completed" className="space-y-3">
          {completed.length === 0 ? (
            <Card className="p-8 text-center text-gray-500">No completed jobs yet.</Card>
          ) : (
            completed.map(renderJobCard)
          )}
        </TabsContent>
      </Tabs>
    </div>
  );
}

'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { NotificationItem } from '@/components/shared/notification-item';
import { EmptyState } from '@/components/shared/empty-state';
import { CheckCheck } from 'lucide-react';
import { Skeleton } from '@/components/ui/skeleton';

export default function NotificationsPage() {
  const [notifications, setNotifications] = useState<any[]>([]);
  const [loading, setLoading] = useState(true);

  useEffect(() => {
    async function fetchNotifications() {
      try {
        const res = await fetch('/api/notifications');
        const data = await res.json();
        setNotifications(data.notifications || []);
      } catch (err) {
        console.error(err);
      } finally {
        setLoading(false);
      }
    }
    fetchNotifications();
  }, []);

  const markAllAsRead = async () => {
    try {
      await fetch('/api/notifications', {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ markAll: true }),
      });
      setNotifications(notifications.map(n => ({ ...n, isRead: true })));
    } catch (err) {
      console.error(err);
    }
  };

  if (loading) {
    return (
      <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-2xl mx-auto w-full">
        <header className="flex items-center justify-between">
          <div>
            <Skeleton className="h-8 w-48 mb-2" />
            <Skeleton className="h-4 w-64" />
          </div>
        </header>
        <div className="flex flex-col gap-2 mt-2">
          {[1, 2, 3, 4].map(i => (
            <div key={i} className="flex gap-4 p-4 border-b">
              <Skeleton className="h-10 w-10 rounded-full shrink-0" />
              <div className="flex-1 space-y-2">
                <div className="flex justify-between">
                  <Skeleton className="h-4 w-1/3" />
                  <Skeleton className="h-3 w-16" />
                </div>
                <Skeleton className="h-3 w-full" />
                <Skeleton className="h-3 w-4/5" />
              </div>
            </div>
          ))}
        </div>
      </div>
    );
  }

  return (
    <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-2xl mx-auto w-full">
      <header className="flex items-center justify-between">
        <div>
          <h1 className="text-2xl font-bold tracking-tight mb-1">Notifications</h1>
          <p className="text-muted-foreground text-sm">Stay updated on your bookings.</p>
        </div>
        {notifications.length > 0 && (
          <Button variant="ghost" size="sm" onClick={markAllAsRead} className="gap-2">
            <CheckCheck className="h-4 w-4" />
            Mark all read
          </Button>
        )}
      </header>

      {notifications.length === 0 ? (
        <EmptyState title="No notifications" description="You're all caught up!" />
      ) : (
        <div className="flex flex-col gap-2">
          {notifications.map(notification => (
            <NotificationItem key={notification.id} notification={notification} />
          ))}
        </div>
      )}
    </div>
  );
}

'use client';

import { useState } from 'react';
import { useRouter } from 'next/navigation';
import { Button } from '@/components/ui/button';
import { Input } from '@/components/ui/input';
import { Card, CardHeader, CardTitle, CardContent } from '@/components/ui/card';
import { Wrench, Loader2 } from 'lucide-react';
import Link from 'next/link';

export default function RegisterPage() {
  const router = useRouter();
  const [loading, setLoading] = useState(false);
  const [formData, setFormData] = useState({
    name: '',
    email: '',
    phone: '',
    password: '',
    role: 'WORKER',
    primaryTrade: 'AC Repair',
    experience: '3',
    address: '',
    isEmergencyAvailable: false,
  });

  const [errors, setErrors] = useState<Record<string, string>>({});
  const [serverError, setServerError] = useState('');

  const validateForm = () => {
    const newErrors: Record<string, string> = {};
    if (!formData.name.trim()) newErrors.name = 'Full legal name is required';
    if (!formData.email.trim() || !/^[^\s@]+@[^\s@]+\.[^\s@]+$/.test(formData.email)) {
      newErrors.email = 'Valid email is required';
    }
    const phoneClean = formData.phone.replace(/\s+/g, '');
    if (!/^(\+91)?[6-9]\d{9}$/.test(phoneClean)) {
      newErrors.phone = 'Valid 10-digit Indian phone number required';
    }
    if (formData.password.length < 6) {
      newErrors.password = 'Password must be at least 6 characters';
    }
    if (!formData.primaryTrade) {
      newErrors.primaryTrade = 'Primary trade is required';
    }
    
    setErrors(newErrors);
    return Object.keys(newErrors).length === 0;
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    setServerError('');
    
    if (!validateForm()) return;

    setLoading(true);
    try {
      const res = await fetch('/api/workers/register', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify(formData),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Registration failed');

      router.push('/login?registered=true');
    } catch (err: any) {
      setServerError(err.message || 'Registration failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <div className="flex flex-col gap-6 p-4 pb-20 md:p-8 max-w-xl mx-auto w-full min-h-[calc(100vh-4rem)]">
      <header className="text-center space-y-1">
        <h1 className="text-2xl font-bold tracking-tight">Join Cooperative Connect</h1>
        <p className="text-xs text-muted-foreground">
          Join Gujarat's leading worker-owned service cooperative. Fair wages, 0% middleman fees & social security.
        </p>
      </header>

      <Card className="border-border/80 shadow-sm">
        <CardHeader>
          <CardTitle className="text-base flex items-center gap-2">
            <Wrench className="h-5 w-5 text-primary" /> Worker & Helper Registration
          </CardTitle>
        </CardHeader>
        <CardContent>
          <form onSubmit={handleSubmit} className="space-y-4 text-xs">
            {serverError && (
              <div className="p-3 bg-destructive/10 border border-destructive/30 rounded-xl text-xs text-destructive font-medium">
                {serverError}
              </div>
            )}
          
            <div>
              <label className="font-semibold block mb-1">Account Type</label>
              <div className="grid grid-cols-2 gap-2">
                <Button
                  type="button"
                  variant={formData.role === 'WORKER' ? 'default' : 'outline'}
                  className="h-10 text-xs font-semibold"
                  onClick={() => setFormData({ ...formData, role: 'WORKER' })}
                >
                  Lead Technician (70% Split)
                </Button>
                <Button
                  type="button"
                  variant={formData.role === 'HELPER' ? 'default' : 'outline'}
                  className="h-10 text-xs font-semibold"
                  onClick={() => setFormData({ ...formData, role: 'HELPER' })}
                >
                  Apprentice / Helper (30% Split)
                </Button>
              </div>
            </div>

            <div>
              <label className="font-semibold block mb-1 text-foreground">Full Legal Name *</label>
              <Input
                value={formData.name}
                onChange={(e) => {
                  setFormData({ ...formData, name: e.target.value });
                  if (errors.name) setErrors({ ...errors, name: '' });
                }}
                placeholder="e.g. Ramesh Patel"
                className={errors.name ? 'border-destructive' : ''}
                disabled={loading}
              />
              {errors.name && <p className="text-destructive mt-1">{errors.name}</p>}
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="font-semibold block mb-1 text-foreground">Email Address *</label>
                <Input
                  type="email"
                  value={formData.email}
                  onChange={(e) => {
                    setFormData({ ...formData, email: e.target.value });
                    if (errors.email) setErrors({ ...errors, email: '' });
                  }}
                  placeholder="name@example.com"
                  className={errors.email ? 'border-destructive' : ''}
                  disabled={loading}
                />
                {errors.email && <p className="text-destructive mt-1">{errors.email}</p>}
              </div>
              <div>
                <label className="font-semibold block mb-1 text-foreground">Phone Number *</label>
                <Input
                  value={formData.phone}
                  onChange={(e) => {
                    setFormData({ ...formData, phone: e.target.value });
                    if (errors.phone) setErrors({ ...errors, phone: '' });
                  }}
                  placeholder="+91 98765 43210"
                  className={errors.phone ? 'border-destructive' : ''}
                  disabled={loading}
                />
                {errors.phone && <p className="text-destructive mt-1">{errors.phone}</p>}
              </div>
            </div>

            <div>
              <label className="font-semibold block mb-1 text-foreground">Password *</label>
              <Input
                type="password"
                value={formData.password}
                onChange={(e) => {
                  setFormData({ ...formData, password: e.target.value });
                  if (errors.password) setErrors({ ...errors, password: '' });
                }}
                placeholder="Min 6 characters"
                className={errors.password ? 'border-destructive' : ''}
                disabled={loading}
              />
              {errors.password && <p className="text-destructive mt-1">{errors.password}</p>}
            </div>

            <div className="grid grid-cols-2 gap-3">
              <div>
                <label className="font-semibold block mb-1 text-foreground">Primary Trade *</label>
                <select
                  value={formData.primaryTrade}
                  onChange={(e) => {
                    setFormData({ ...formData, primaryTrade: e.target.value });
                    if (errors.primaryTrade) setErrors({ ...errors, primaryTrade: '' });
                  }}
                  className={`w-full p-2.5 border rounded-md bg-background text-foreground text-xs h-10 ${errors.primaryTrade ? 'border-destructive' : 'border-input'}`}
                  disabled={loading}
                >
                  <option value="">Select a trade</option>
                  <option value="AC Repair">AC Repair & Servicing</option>
                  <option value="Electrician">Electrician</option>
                  <option value="Plumber">Plumber</option>
                  <option value="Carpenter">Carpenter</option>
                  <option value="Painter">Painter</option>
                  <option value="Cleaner">Home Cleaning</option>
                  <option value="Appliance Repair">Appliance Repair</option>
                </select>
                {errors.primaryTrade && <p className="text-destructive mt-1">{errors.primaryTrade}</p>}
              </div>
              <div>
                <label className="font-semibold block mb-1 text-foreground">Years of Experience</label>
                <Input
                  type="number"
                  min={0}
                  value={formData.experience}
                  onChange={(e) => setFormData({ ...formData, experience: e.target.value })}
                  disabled={loading}
                />
              </div>
            </div>

            <div>
              <label className="font-semibold block mb-1 text-foreground">Operational Area in Ahmedabad</label>
              <Input
                value={formData.address}
                onChange={(e) => setFormData({ ...formData, address: e.target.value })}
                placeholder="e.g. Satellite / Vastrapur / Navrangpura"
                disabled={loading}
              />
            </div>

            <div className="flex items-center gap-2 pt-1">
              <input
                type="checkbox"
                id="emergency"
                checked={formData.isEmergencyAvailable}
                onChange={(e) => setFormData({ ...formData, isEmergencyAvailable: e.target.checked })}
                className="rounded border-border"
                disabled={loading}
              />
              <label htmlFor="emergency" className="font-medium text-foreground cursor-pointer">
                Opt-in for 24/7 Emergency Service Dispatch (+25% surcharge bonus)
              </label>
            </div>

            <Button
              type="submit"
              size="lg"
              className="w-full h-12 text-sm font-bold gap-2 mt-4"
              disabled={loading}
            >
              {loading ? (
                <>
                  <Loader2 className="w-4 h-4 animate-spin" /> Submitting...
                </>
              ) : 'Complete Registration'}
            </Button>

            <p className="text-center text-muted-foreground pt-2">
              Already a cooperative member?{' '}
              <Link href="/login" className="text-primary font-bold hover:underline">
                Sign In
              </Link>
            </p>
          </form>
        </CardContent>
      </Card>
    </div>
  );
}

'use client';

import React, { useState } from 'react';
import { Button } from '@/components/ui/button';
import { Card, CardContent } from '@/components/ui/card';
import { CreditCard, AlertTriangle, RefreshCw } from 'lucide-react';
import { toast } from 'sonner';
import { useRouter } from 'next/navigation';

interface CustomerBookingActionsProps {
  bookingId: string;
  invoice: any;
  payment: any;
  status: string;
}

export function CustomerBookingActions({ bookingId, invoice, payment, status }: CustomerBookingActionsProps) {
  const router = useRouter();
  const [loadingPay, setLoadingPay] = useState(false);
  const [disputeOpen, setDisputeOpen] = useState(false);
  const [disputeCategory, setDisputeCategory] = useState('POOR_QUALITY');
  const [disputeDesc, setDisputeDesc] = useState('');
  const [loadingDispute, setLoadingDispute] = useState(false);
  const [loadingCancel, setLoadingCancel] = useState(false);

  const handleCancel = async () => {
    if (!confirm("Are you sure you want to cancel this booking?")) return;

    setLoadingCancel(true);
    try {
      const res = await fetch(`/api/bookings/${bookingId}`, {
        method: 'PATCH',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({ status: 'CANCELLED' }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to cancel booking');

      toast.success('Booking cancelled successfully');
      router.refresh();
    } catch (err: any) {
      toast.error(err.message || 'Cancellation failed');
    } finally {
      setLoadingCancel(false);
    }
  };

  const handlePay = async () => {
    const totalAmount = invoice?.total || 450;
    setLoadingPay(true);
    try {
      const res = await fetch('/api/payments', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bookingId,
          amount: totalAmount,
          method: 'UPI',
          provider: 'SANDBOX',
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Payment failed');

      toast.success(`Payment of ₹${totalAmount} successful! Warranty activated.`);
      router.refresh();
    } catch (err: any) {
      toast.error(err.message || 'Payment processing failed');
    } finally {
      setLoadingPay(false);
    }
  };

  const handleDispute = async (e: React.FormEvent) => {
    e.preventDefault();
    if (!disputeDesc.trim()) return toast.error('Please enter a description for the complaint');
    setLoadingDispute(true);
    try {
      const res = await fetch(`/api/bookings/${bookingId}/complaint`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          category: disputeCategory,
          description: disputeDesc,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Failed to file complaint');

      toast.success('Complaint submitted to Cooperative Dispute Committee');
      setDisputeOpen(false);
      setDisputeDesc('');
      router.refresh();
    } catch (err: any) {
      toast.error(err.message || 'Complaint filing failed');
    } finally {
      setLoadingDispute(false);
    }
  };

  const isCompleted = status === 'COMPLETED';
  const hasPaid = !!payment || invoice?.status === 'PAID';
  const canUploadBefore = ['ACCEPTED', 'TRAVELLING', 'ARRIVED', 'IN_PROGRESS'].includes(status);

  const [uploadingBefore, setUploadingBefore] = useState(false);
  const handleBeforePhoto = async (e: React.ChangeEvent<HTMLInputElement>) => {
    const file = e.target.files?.[0];
    if (!file) return;

    setUploadingBefore(true);
    try {
      const formData = new FormData();
      formData.append('file', file);

      const uploadRes = await fetch('/api/upload?type=public', {
        method: 'POST',
        body: formData,
      });
      const uploadData = await uploadRes.json();
      if (!uploadRes.ok) throw new Error(uploadData.error || 'Upload failed');

      const res = await fetch(`/api/bookings/${bookingId}/proof`, {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          type: 'BEFORE',
          imageUrl: uploadData.url,
          caption: `BEFORE servicing inspection photo by customer`,
        }),
      });
      const data = await res.json();
      if (!res.ok) throw new Error(data.error || 'Photo DB save failed');

      toast.success('Before photo uploaded successfully');
      router.refresh();
    } catch (err: any) {
      toast.error(err.message || 'Failed to upload photo');
    } finally {
      setUploadingBefore(false);
    }
  };

  return (
    <div className="space-y-4">
      {status === 'REQUESTED' && (
        <Card className="border-destructive bg-destructive/5 p-4">
          <CardContent className="p-0 flex flex-col sm:flex-row items-center justify-between gap-4">
            <div>
              <h4 className="font-bold text-sm text-foreground">Cancel Booking</h4>
              <p className="text-xs text-muted-foreground">You can cancel the booking before the worker accepts it.</p>
            </div>
            <Button
              onClick={handleCancel}
              disabled={loadingCancel}
              variant="destructive"
              className="w-full sm:w-auto font-bold gap-2"
            >
              {loadingCancel ? (
                <><RefreshCw className="h-4 w-4 animate-spin" /> Cancelling...</>
              ) : (
                'Cancel Booking'
              )}
            </Button>
          </CardContent>
        </Card>
      )}

      {isCompleted && !hasPaid && invoice && (
        <Card className="border-primary bg-primary/5 p-4">
          <CardContent className="p-0 flex flex-col sm:flex-row items-center justify-between gap-4">
            <div>
              <h4 className="font-bold text-sm text-foreground">Pending Payment</h4>
              <p className="text-xs text-muted-foreground">Total due: ₹{invoice.total}. Instant digital invoice settlement via Sandbox UPI.</p>
            </div>
            <Button
              onClick={handlePay}
              disabled={loadingPay}
              className="w-full sm:w-auto bg-primary text-primary-foreground font-bold gap-2"
            >
              {loadingPay ? (
                <>
                  <RefreshCw className="h-4 w-4 animate-spin" /> Processing UPI...
                </>
              ) : (
                <>
                  <CreditCard className="h-4 w-4" /> Pay ₹{invoice.total} (Sandbox UPI)
                </>
              )}
            </Button>
          </CardContent>
        </Card>
      )}

      {canUploadBefore && (
        <Card className="border-primary/50 bg-primary/5 p-4">
          <CardContent className="p-0 flex flex-col sm:flex-row items-center justify-between gap-4">
            <div>
              <h4 className="font-bold text-sm text-foreground">Service Evidence</h4>
              <p className="text-xs text-muted-foreground">Upload a BEFORE photo of the issue for records.</p>
            </div>
            <div className="relative w-full sm:w-auto">
              <input 
                type="file" 
                accept="image/*" 
                onChange={handleBeforePhoto} 
                className="absolute inset-0 w-full h-full opacity-0 cursor-pointer disabled:cursor-not-allowed" 
                disabled={uploadingBefore}
              />
              <Button
                variant="outline"
                className="w-full sm:w-auto font-bold pointer-events-none"
              >
                {uploadingBefore ? (
                  <><RefreshCw className="h-4 w-4 mr-2 animate-spin" /> Uploading...</>
                ) : (
                  'Upload Before Photo'
                )}
              </Button>
            </div>
          </CardContent>
        </Card>
      )}

      {/* Dispute Modal / Toggle */}
      {disputeOpen ? (
        <Card className="border-destructive/30 bg-destructive/5 p-4">
          <form onSubmit={handleDispute} className="space-y-3 text-xs">
            <div className="flex justify-between items-center">
              <h4 className="font-bold text-sm text-destructive flex items-center gap-1.5">
                <AlertTriangle className="h-4 w-4" /> Report Issue to Cooperative
              </h4>
              <button
                type="button"
                onClick={() => setDisputeOpen(false)}
                className="text-muted-foreground hover:text-foreground font-bold"
              >
                Cancel
              </button>
            </div>
            <div>
              <label className="font-medium text-foreground block mb-1">Issue Category</label>
              <select
                value={disputeCategory}
                onChange={(e) => setDisputeCategory(e.target.value)}
                className="w-full p-2 border rounded-md bg-background text-foreground text-xs"
              >
                <option value="POOR_QUALITY">Poor Service Quality / Incomplete Work</option>
                <option value="OVERCHARGED">Pricing / Material Discrepancy</option>
                <option value="BEHAVIOUR">Worker Conduct / Delay</option>
                <option value="DAMAGE">Accidental Property Damage</option>
              </select>
            </div>
            <div>
              <label className="font-medium text-foreground block mb-1">Details</label>
              <textarea
                value={disputeDesc}
                onChange={(e) => setDisputeDesc(e.target.value)}
                placeholder="Describe what went wrong..."
                className="w-full p-2 border rounded-md bg-background text-foreground text-xs min-h-[70px]"
              />
            </div>
            <Button
              type="submit"
              disabled={loadingDispute}
              variant="destructive"
              size="sm"
              className="w-full font-semibold"
            >
              {loadingDispute ? 'Submitting to Cooperative...' : 'Submit Dispute Claim'}
            </Button>
          </form>
        </Card>
      ) : (
        <div className="pt-2 flex justify-center">
          <Button
            variant="ghost"
            size="sm"
            onClick={() => setDisputeOpen(true)}
            className="text-destructive hover:bg-destructive/10 hover:text-destructive gap-1.5 text-xs"
          >
            <AlertTriangle className="h-3.5 w-3.5" /> Report an Issue / Submit Complaint
          </Button>
        </div>
      )}
    </div>
  );
}

