'use client';

import { useState, useEffect } from 'react';
import { Button } from '@/components/ui/button';
import { Heart, Loader2 } from 'lucide-react';
import { toast } from 'sonner';
import { cn } from '@/lib/utils';
import { useRouter } from 'next/navigation';

interface TrustedWorkerButtonProps {
  workerId: string;
  initialIsTrusted?: boolean;
  className?: string;
  variant?: 'default' | 'outline' | 'ghost';
  size?: 'default' | 'sm' | 'lg' | 'icon';
  showText?: boolean;
}

export function TrustedWorkerButton({ 
  workerId, 
  initialIsTrusted = false, 
  className,
  variant = 'outline',
  size = 'default',
  showText = true
}: TrustedWorkerButtonProps) {
  const [isTrusted, setIsTrusted] = useState(initialIsTrusted);
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  useEffect(() => {
    setIsTrusted(initialIsTrusted);
  }, [initialIsTrusted]);

  const toggleTrusted = async () => {
    setLoading(true);
    try {
      if (isTrusted) {
        const res = await fetch(`/api/customers/trusted?workerId=${workerId}`, { method: 'DELETE' });
        if (!res.ok) throw new Error('Failed to remove from trusted workers');
        setIsTrusted(false);
        toast.success('Removed from trusted workers');
      } else {
        const res = await fetch('/api/customers/trusted', {
          method: 'POST',
          headers: { 'Content-Type': 'application/json' },
          body: JSON.stringify({ workerId }),
        });
        if (!res.ok) throw new Error('Failed to add to trusted workers');
        setIsTrusted(true);
        toast.success('Added to trusted workers');
      }
      router.refresh();
    } catch (err: any) {
      toast.error(err.message || 'Operation failed');
    } finally {
      setLoading(false);
    }
  };

  return (
    <Button
      variant={isTrusted ? 'default' : variant}
      size={size}
      className={cn("gap-2 transition-all z-10", isTrusted ? "bg-rose-500 hover:bg-rose-600 text-white border-rose-500" : "", className)}
      onClick={(e) => {
        e.preventDefault(); // Prevent linking if inside a Link tag
        e.stopPropagation();
        toggleTrusted();
      }}
      disabled={loading}
    >
      {loading ? (
        <Loader2 className="h-4 w-4 animate-spin" />
      ) : (
        <Heart className={cn("h-4 w-4", isTrusted ? "fill-current" : "")} />
      )}
      {showText && (isTrusted ? 'Trusted' : 'Add to Trusted')}
    </Button>
  );
}

"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { Plus } from "lucide-react";
import { Button } from "@/components/ui/button";
import {
  Dialog,
  DialogContent,
  DialogDescription,
  DialogFooter,
  DialogHeader,
  DialogTitle,
  DialogTrigger,
} from "@/components/ui/dialog";
import { Input } from "@/components/ui/input";
import { Label } from "@/components/ui/label";
import { toast } from "sonner";
import { Textarea } from "@/components/ui/textarea";

export function AddLocationDialog({ type }: { type: "SOCIETY" | "INSTITUTION" }) {
  const [open, setOpen] = useState(false);
  const [loading, setLoading] = useState(false);
  const router = useRouter();

  const handleSubmit = async (e: React.FormEvent<HTMLFormElement>) => {
    e.preventDefault();
    setLoading(true);

    const formData = new FormData(e.currentTarget);
    const data = {
      name: formData.get("name") as string,
      address: formData.get("address") as string,
      buildingDetails: formData.get("buildingDetails") as string,
      accessInstructions: formData.get("accessInstructions") as string,
    };

    try {
      const res = await fetch("/api/organization/locations", {
        method: "POST",
        headers: { "Content-Type": "application/json" },
        body: JSON.stringify(data),
      });

      const json = await res.json();
      if (!res.ok) throw new Error(json.error || "Failed to add location");

      toast.success("Location added successfully!");
      setOpen(false);
      router.refresh();
    } catch (err: any) {
      toast.error(err.message);
    } finally {
      setLoading(false);
    }
  };

  return (
    <Dialog open={open} onOpenChange={setOpen}>
      <DialogTrigger asChild>
        <Button>
          <Plus className="w-4 h-4 mr-2" />
          Add Location
        </Button>
      </DialogTrigger>
      <DialogContent className="sm:max-w-[425px]">
        <form onSubmit={handleSubmit}>
          <DialogHeader>
            <DialogTitle>Add New Location</DialogTitle>
            <DialogDescription>
              Add a new service area within your {type === "SOCIETY" ? "society" : "institution"}.
            </DialogDescription>
          </DialogHeader>
          <div className="grid gap-4 py-4">
            <div className="grid gap-2">
              <Label htmlFor="name">Location Name *</Label>
              <Input
                id="name"
                name="name"
                placeholder="e.g., Tower A, Main Building, Block C"
                required
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="address">Address (Optional)</Label>
              <Input
                id="address"
                name="address"
                placeholder="Specific address or landmark"
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="buildingDetails">Building Details (Optional)</Label>
              <Input
                id="buildingDetails"
                name="buildingDetails"
                placeholder="e.g., Floors 1-5, Wing B"
              />
            </div>
            <div className="grid gap-2">
              <Label htmlFor="accessInstructions">Access Instructions (Optional)</Label>
              <Textarea
                id="accessInstructions"
                name="accessInstructions"
                placeholder="Gate code, security desk info, etc."
                className="resize-none h-20"
              />
            </div>
          </div>
          <DialogFooter>
            <Button type="button" variant="outline" onClick={() => setOpen(false)}>
              Cancel
            </Button>
            <Button type="submit" disabled={loading}>
              {loading ? "Adding..." : "Add Location"}
            </Button>
          </DialogFooter>
        </form>
      </DialogContent>
    </Dialog>
  );
}

'use client';

import { useState } from 'react';
import { Button } from '@/components/ui/button';
import { AlertCircle, PhoneCall, ShieldAlert, Loader2 } from 'lucide-react';
import { toast } from 'sonner';

interface SOSButtonProps {
  bookingId?: string;
  className?: string;
}

export function SOSButton({ bookingId, className }: SOSButtonProps) {
  const [isOpen, setIsOpen] = useState(false);
  const [loading, setLoading] = useState(false);

  const handleSOS = async (type: 'POLICE' | 'SAFETY_TEAM' | 'REPORT') => {
    if (type === 'POLICE') {
      window.location.href = 'tel:112'; // Default emergency number in India
      return;
    }

    setLoading(true);
    try {
      // Get location if possible
      let lat: number | undefined;
      let lng: number | undefined;

      try {
        if (navigator.geolocation) {
          const pos = await new Promise<GeolocationPosition>((resolve, reject) => {
            navigator.geolocation.getCurrentPosition(resolve, reject, { timeout: 5000 });
          });
          lat = pos.coords.latitude;
          lng = pos.coords.longitude;
        }
      } catch (_e) {
        console.warn('Could not get location for SOS');
      }

      const res = await fetch('/api/sos', {
        method: 'POST',
        headers: { 'Content-Type': 'application/json' },
        body: JSON.stringify({
          bookingId,
          latitude: lat,
          longitude: lng,
          description: type === 'SAFETY_TEAM' ? 'Emergency assistance requested' : 'Safety report filed',
        }),
      });

      if (!res.ok) throw new Error('Failed to trigger SOS');

      toast.error(
        type === 'SAFETY_TEAM'
          ? 'Safety Team has been alerted. They will contact you immediately.'
          : 'Incident reported successfully.',
        {
          duration: 10000,
          icon: <ShieldAlert className="w-5 h-5 text-red-500" />,
        }
      );
      setIsOpen(false);
    } catch (_error) {
      toast.error('Failed to trigger alert. Please call 112 directly.');
    } finally {
      setLoading(false);
    }
  };

  if (!isOpen) {
    return (
      <Button
        variant="destructive"
        onClick={() => setIsOpen(true)}
        className={`rounded-full font-bold shadow-lg flex items-center gap-2 ${className || ''}`}
      >
        <AlertCircle className="w-5 h-5" />
        SOS
      </Button>
    );
  }

  return (
    <div className={`bg-red-50 border-2 border-red-500 rounded-lg p-4 shadow-xl ${className || ''}`}>
      <h3 className="font-bold text-red-800 flex items-center gap-2 mb-3">
        <ShieldAlert className="w-5 h-5" /> Emergency Options
      </h3>
      <p className="text-xs text-red-700 mb-4">
        If you are in immediate danger, contact emergency services.
      </p>
      <div className="space-y-2">
        <Button
          variant="destructive"
          className="w-full flex justify-start gap-3"
          onClick={() => handleSOS('POLICE')}
        >
          <PhoneCall className="w-4 h-4" /> Call Police (112)
        </Button>
        <Button
          variant="outline"
          className="w-full flex justify-start gap-3 border-red-200 hover:bg-red-100 text-red-800"
          onClick={() => handleSOS('SAFETY_TEAM')}
          disabled={loading}
        >
          {loading ? <Loader2 className="w-4 h-4 animate-spin" /> : <ShieldAlert className="w-4 h-4" />}
          Alert Co-opConnect Safety Team
        </Button>
        <Button
          variant="ghost"
          className="w-full text-muted-foreground mt-2"
          onClick={() => setIsOpen(false)}
          disabled={loading}
        >
          Cancel
        </Button>
      </div>
    </div>
  );
}

import React from "react";
import Link from "next/link";
import { Card, CardContent, CardHeader } from "@/components/ui/card";
import { Badge } from "@/components/ui/badge";
import { cn, formatCurrency, formatDate, getStatusColor } from "@/lib/utils";
import { Calendar, User } from "lucide-react";

export function BookingCard({ booking, href, className }: { booking: any; href?: string; className?: string }) {
  const categoryName = booking.category?.name || booking.category || "Service";
  const workerName = booking.worker?.user?.name || booking.worker?.name || booking.worker;
  const description = booking.description || `${categoryName} Request`;
  const date = booking.scheduledDate || booking.createdAt || new Date();
  const price = booking.finalPrice || booking.estimatedPrice || booking.category?.basePrice || 350;
  const targetHref = href || `/customer/bookings/${booking.id}`;

  return (
    <Link href={targetHref} className="block h-full group">
      <Card className={cn("h-full transition-all duration-200 hover:border-primary/50 hover:shadow-lg hover:shadow-primary/5 bg-card border-border/80 flex flex-col", className)}>
        <CardHeader className="flex flex-row items-start justify-between gap-4 space-y-0 p-4 pb-2">
          <div className="flex-1 space-y-1">
            <div className="flex items-center gap-2">
              <Badge variant="outline" className="text-xs bg-secondary/70 border-border text-foreground">{categoryName}</Badge>
            </div>
            <h4 className="font-bold text-foreground group-hover:text-primary transition-colors text-sm line-clamp-1">{description}</h4>
          </div>
          <Badge className={cn("shrink-0 text-xs font-semibold", getStatusColor(booking.status))}>
            {booking.status.replace(/_/g, ' ')}
          </Badge>
        </CardHeader>
        <CardContent className="p-4 pt-2 text-xs text-muted-foreground flex-1 flex flex-col justify-end space-y-1.5">
          {workerName && (
            <div className="flex items-center gap-1.5 text-foreground/90">
              <User className="h-3.5 w-3.5 text-muted-foreground" />
              <span className="font-medium truncate">{workerName}</span>
            </div>
          )}
          <div className="flex items-center gap-1.5 text-muted-foreground">
            <Calendar className="h-3.5 w-3.5 text-muted-foreground" />
            <span>{formatDate(date)}</span>
          </div>
          <div className="flex items-center justify-between font-bold text-foreground pt-2 border-t border-border mt-1">
            <span className="text-[11px] text-muted-foreground font-normal">Amount:</span>
            <span className="text-sm text-primary font-bold">{formatCurrency(price)}</span>
          </div>
        </CardContent>
      </Card>
    </Link>
  );
}

import React from "react";
import { cn, formatDate, getStatusColor } from "@/lib/utils";

interface TimelineEvent {
  status: string;
  createdAt: string | Date;
  note?: string | null;
}

interface BookingTimelineProps {
  statusHistory?: TimelineEvent[] | any[];
  status?: string;
  className?: string;
}

export function BookingTimeline({ statusHistory, status, className }: BookingTimelineProps) {
  const events = statusHistory && statusHistory.length > 0 
    ? statusHistory 
    : status 
    ? [{ status, createdAt: new Date(), note: "Current Status" }] 
    : [];

  if (events.length === 0) return null;

  return (
    <div className={cn("space-y-3", className)}>
      {events.map((event, index) => {
        const isLast = index === events.length - 1;
        const colorClass = getStatusColor(event.status);

        let dotColor = "bg-primary";
        if (colorClass.includes("yellow")) dotColor = "bg-amber-500";
        if (colorClass.includes("blue")) dotColor = "bg-blue-500";
        if (colorClass.includes("green")) dotColor = "bg-green-600";
        if (colorClass.includes("red")) dotColor = "bg-red-500";
        if (colorClass.includes("slate") || colorClass.includes("gray")) dotColor = "bg-gray-400";

        return (
          <div key={`${event.status}-${index}`} className="relative flex gap-3">
            {!isLast && (
              <div className="absolute left-2.5 top-4 bottom-[-0.75rem] w-0.5 bg-gray-200" />
            )}
            <div className="relative mt-0.5 flex h-5 w-5 shrink-0 items-center justify-center">
              <div className={cn("h-2.5 w-2.5 rounded-full ring-4 ring-white", dotColor)} />
            </div>
            <div className="flex flex-col pb-3">
              <span className="font-bold text-xs text-gray-900">
                {event.status.replace(/_/g, ' ')}
              </span>
              <span className="text-[11px] text-gray-400">
                {formatDate(new Date(event.createdAt))}
              </span>
              {event.note && (
